import { useEffect, useState } from "react";

interface Room {
  id: number;
  name: string;
  capacity: number;
  equipment: string[];
}

interface Booking {
  id: number;
  roomId: number;
  memberId: number;
  startTime: string;
  endTime: string;
}

export function RoomBookingView() {
  const [rooms, setRooms] = useState<Room[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedRoomId, setSelectedRoomId] = useState<number | null>(null);
  const [startTime, setStartTime] = useState("");
  const [endTime, setEndTime] = useState("");

  useEffect(() => {
    fetchRooms();
    fetchBookings();
  }, []);

  const fetchRooms = async () => {
    try {
      const response = await fetch("/api/rooms-api/");
      if (!response.ok) throw new Error("Failed to fetch rooms");
      const data = await response.json();
      setRooms(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const fetchBookings = async () => {
    try {
      const response = await fetch("/api/rooms-api/");
      if (!response.ok) throw new Error("Failed to fetch bookings");
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleBookRoom = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedRoomId || !startTime || !endTime) return;

    try {
      const response = await fetch("/api/rooms-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          roomId: selectedRoomId,
          memberId: 1, // Assuming current member ID is 1
          startTime,
          endTime,
        }),
      });

      if (!response.ok) throw new Error("Failed to book room");

      // Reset form
      setSelectedRoomId(null);
      setStartTime("");
      setEndTime("");

      // Refresh data
      await fetchRooms();
      await fetchBookings();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center" }}>{error}</div>;

  return (
    <div style={{ maxWidth: 800, margin: "0 auto", padding: 20, fontFamily: "system-ui, sans-serif" }}>
      <h1>Room Booking</h1>

      <form onSubmit={handleBookRoom} style={{ marginBottom: 30 }}>
        <h2>Book a Room</h2>
        <div style={{ marginBottom: 10 }}>
          <label htmlFor="roomSelect">Select Room:</label>
          <select
            id="roomSelect"
            value={selectedRoomId || ""}
            onChange={(e) => setSelectedRoomId(Number(e.target.value))}
            style={{ width: "100%", padding: 8, borderRadius: 4 }}
          >
            <option value="">Choose a room</option>
            {rooms.map((room) => (
              <option key={room.id} value={room.id}>
                {room.name}
              </option>
            ))}
          </select>
        </div>

        <div style={{ marginBottom: 10 }}>
          <label htmlFor="startTime">Start Time:</label>
          <input
            type="datetime-local"
            id="startTime"
            value={startTime}
            onChange={(e) => setStartTime(e.target.value)}
            style={{ width: "100%", padding: 8, borderRadius: 4 }}
          />
        </div>

        <div style={{ marginBottom: 10 }}>
          <label htmlFor="endTime">End Time:</label>
          <input
            type="datetime-local"
            id="endTime"
            value={endTime}
            onChange={(e) => setEndTime(e.target.value)}
            style={{ width: "100%", padding: 8, borderRadius: 4 }}
          />
        </div>

        <button
          type="submit"
          style={{
            backgroundColor: "#007bff",
            color: "white",
            border: "none",
            padding: "10px 20px",
            borderRadius: 4,
            cursor: "pointer",
          }}
        >
          Book Room
        </button>
      </form>

      <h2>Available Rooms</h2>
      {rooms.length === 0 ? (
        <p>No rooms available.</p>
      ) : (
        <div style={{ display: "flex", flexWrap: "wrap", gap: 20 }}>
          {rooms.map((room) => (
            <div
              key={room.id}
              style={{
                border: "1px solid #ccc",
                borderRadius: 8,
                padding: 15,
                width: "calc(50% - 10px)",
                boxSizing: "border-box",
              }}
            >
              <h3>{room.name}</h3>
              <p>Capacity: {room.capacity}</p>
              <p>Equipment: {room.equipment.join(", ")}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

interface Booking {
  id: string;
  roomId: string;
  startDate: string;
  endDate: string;
  startTime: string;
  endTime: string;
}

interface Room {
  id: string;
  name: string;
  capacity: number;
}

export function AdminDoubleBookGuard() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [rooms, setRooms] = useState<Room[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [bookingsResponse, roomsResponse] = await Promise.all([
          fetch('/api/rooms-api/'),
          fetch('/api/rooms-api'),
        ]);

        if (!bookingsResponse.ok || !roomsResponse.ok) {
          throw new Error('Failed to fetch data');
        }

        const bookingsData = await bookingsResponse.json();
        const roomsData = await roomsResponse.json();

        setBookings(bookingsData);
        setRooms(roomsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    const formData = new FormData(e.currentTarget);
    const newBooking = {
      roomId: formData.get('roomId') as string,
      startDate: formData.get('startDate') as string,
      endDate: formData.get('endDate') as string,
      startTime: formData.get('startTime') as string,
      endTime: formData.get('endTime') as string,
    };

    try {
      const response = await fetch('/api/double-booking-guard/bookings', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(newBooking),
      });

      if (!response.ok) {
        throw new Error('Booking failed due to double booking');
      }

      // Refresh data after successful booking
      const [bookingsResponse, roomsResponse] = await Promise.all([
        fetch('/api/rooms-api/'),
        fetch('/api/rooms-api'),
      ]);

      if (bookingsResponse.ok && roomsResponse.ok) {
        const bookingsData = await bookingsResponse.json();
        const roomsData = await roomsResponse.json();

        setBookings(bookingsData);
        setRooms(roomsData);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Admin Double-Book Guard</h1>

      <h2>Current Bookings</h2>
      {bookings.length === 0 ? (
        <p>No bookings found.</p>
      ) : (
        <table style={{ width: '100%', borderCollapse: 'collapse', marginBottom: '20px' }}>
          <thead>
            <tr style={{ borderBottom: '1px solid #ccc' }}>
              <th style={{ textAlign: 'left', padding: '8px' }}>Room</th>
              <th style={{ textAlign: 'left', padding: '8px' }}>Start Date</th>
              <th style={{ textAlign: 'left', padding: '8px' }}>End Date</th>
              <th style={{ textAlign: 'left', padding: '8px' }}>Start Time</th>
              <th style={{ textAlign: 'left', padding: '8px' }}>End Time</th>
            </tr>
          </thead>
          <tbody>
            {bookings.map(booking => {
              const room = rooms.find(r => r.id === booking.roomId);
              return (
                <tr key={booking.id} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '8px' }}>{room?.name || 'Unknown Room'}</td>
                  <td style={{ padding: '8px' }}>{booking.startDate}</td>
                  <td style={{ padding: '8px' }}>{booking.endDate}</td>
                  <td style={{ padding: '8px' }}>{booking.startTime}</td>
                  <td style={{ padding: '8px' }}>{booking.endTime}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}

      <h2>Create New Booking</h2>
      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        <div>
          <label htmlFor="roomId">Room:</label>
          <select id="roomId" name="roomId" required style={{ width: '100%', padding: '8px', marginTop: '5px' }}>
            <option value="">Select a room</option>
            {rooms.map(room => (
              <option key={room.id} value={room.id}>{room.name}</option>
            ))}
          </select>
        </div>

        <div>
          <label htmlFor="startDate">Start Date:</label>
          <input 
            type="date" 
            id="startDate" 
            name="startDate" 
            required 
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
          />
        </div>

        <div>
          <label htmlFor="endDate">End Date:</label>
          <input 
            type="date" 
            id="endDate" 
            name="endDate" 
            required 
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
          />
        </div>

        <div>
          <label htmlFor="startTime">Start Time:</label>
          <input 
            type="time" 
            id="startTime" 
            name="startTime" 
            required 
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
          />
        </div>

        <div>
          <label htmlFor="endTime">End Time:</label>
          <input 
            type="time" 
            id="endTime" 
            name="endTime" 
            required 
