import { useEffect, useState } from "react";

interface Reservation {
  id: string;
  customerName: string;
  email: string;
  date: string;
  time: string;
  guests: number;
}

export function OwnerExportPanel() {
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchReservations();
  }, []);

  const fetchReservations = async () => {
    try {
      const response = await fetch("/api/reservations-api/reservations");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setReservations(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleDownloadCSV = () => {
    const headers = ["ID", "Customer Name", "Email", "Date", "Time", "Guests"];
    const csvContent = [
      headers.join(","),
      ...reservations.map(r => [
        r.id,
        `"${r.customerName}"`,
        `"${r.email}"`,
        `"${r.date}"`,
        `"${r.time}"`,
        r.guests.toString()
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "reservations.csv");
    link.style.visibility = "hidden";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px" }}>
      <h1 style={{ textAlign: "center", fontFamily: "sans-serif" }}>
        Owner Export Panel
      </h1>
      <p style={{ textAlign: "center", fontFamily: "sans-serif" }}>
        Download all reservations as CSV
      </p>
      <div style={{ textAlign: "center", marginBottom: "20px" }}>
        <button
          onClick={handleDownloadCSV}
          style={{
            backgroundColor: "#4CAF50",
            border: "none",
            color: "white",
            padding: "10px 20px",
            textAlign: "center",
            textDecoration: "none",
            display: "inline-block",
            fontSize: "16px",
            margin: "4px 2px",
            cursor: "pointer",
            borderRadius: "4px",
            fontFamily: "sans-serif"
          }}
        >
          Download CSV
        </button>
      </div>
      <div style={{ fontFamily: "sans-serif" }}>
        {reservations.length === 0 ? (
          <p>No reservations found.</p>
        ) : (
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>ID</th>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>Customer Name</th>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>Email</th>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>Date</th>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>Time</th>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>Guests</th>
              </tr>
            </thead>
            <tbody>
              {reservations.map(reservation => (
                <tr key={reservation.id}>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {reservation.id}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {reservation.customerName}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {reservation.email}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {reservation.date}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {reservation.time}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {reservation.guests}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
