      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const fetchAvailableDesks = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/bookings-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch available desks: ${response.status} ${response.statusText}`);
