    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleBookDesk = async (date: string) => {
    try {
      const response = await fetch('/api/bookings-api/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          date,
          memberId: 'current-member-id', // This should come from auth context
          deskId: 'desk-1', // This should be dynamic
        }),
      });

      if (!response.ok) {
        throw new Error(`Failed to book desk: ${response.status} ${response.statusText}`);
      }

      await fetchBookings();
      await fetchAvailableDesks();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const formatDate = (dateString: string) => {
    const options: Intl.DateTimeFormatOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
