      <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        {availableDesks.length > 0 ? (
          availableDesks.map((desk) => (
            <div 
              key={desk.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center'
              }}
            >
              <span>{formatDate(desk.date)}</span>
              <button 
                onClick={() => handleBookDesk(desk.date)}
                disabled={!desk.available}
                style={{ 
                  backgroundColor: desk.available ? '#007bff' : '#ccc', 
                  color: 'white', 
                  border: 'none', 
                  padding: '8px 16px', 
                  borderRadius: '4px', 
                  cursor: desk.available ? 'pointer' : 'default'
                }}
              >
                {desk.available ? 'Book Desk' : 'Unavailable'}
              </button>
            </div>
          ))
        ) : (
          <p style={{ textAlign: 'center', padding: '20px' }}>No available desks found.</p>
        )}
      </div>
    </div>
  );
