        <div style={{ marginBottom: '15px' }}>
          <label>Date:</label>
          <input
            type="date"
            name="date"
            value={formData.date}
            onChange={handleChange}
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label>Client:</label>
          <input
            type="text"
            name="client"
            value={formData.client}
            onChange={handleChange}
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label>Task:</label>
          <input
            type="text"
            name="task"
            value={formData.task}
            onChange={handleChange}
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label>Hours:</label>
          <input
            type="number"
            name="hours"
            value={formData.hours}
            onChange={handleChange}
            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
            min="0"
            step="0.25"
            required
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: '#007bff', 
            color: 'white', 
            border: 'none', 
            padding: '10px 20px', 
            borderRadius: '4px', 
            cursor: 'pointer' 
          }}
        >
          Submit Entry
        </button>
      </form>

      <h2 style={{ textAlign: 'center' }}>Recent Entries</h2>
      {entries.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No entries found.</p>
      ) : (
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ borderBottom: '1px solid #ddd' }}>
              <th style={{ padding: '10px', textAlign: 'left' }}>Date</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Client</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Task</th>
              <th style={{ padding: '10px', textAlign: 'left' }}>Hours</th>
            </tr>
          </thead>
          <tbody>
            {entries.map(entry => (
              <tr key={entry.id} style={{ borderBottom: '1px solid #eee' }}>
                <td style={{ padding: '10px' }}>{entry.date}</td>
                <td style={{ padding: '10px' }}>{entry.client}</td>
                <td style={{ padding: '10px' }}>{entry.task}</td>
                <td style={{ padding: '10px' }}>{entry.hours}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

