export function SupervisorOnlyDeleteGuard() {
  const [timesheetEntries, setTimesheetEntries] = useState<TimesheetEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<{ id: number; role: string } | null>(null);

  useEffect(() => {
    // Simulate fetching current user
    const fetchCurrentUser = async () => {
      // In a real app, this would be an API call
      // For demo purposes, we'll assume a supervisor with ID 1
      setCurrentUser({ id: 1, role: "supervisor" });
    };

    const fetchTimesheetEntries = async () => {
      try {
        const response = await fetch("/api/timesheets-api/");
        if (!response.ok) {
          throw new Error(`Failed to fetch timesheet entries: ${response.status}`);
        }
        const data = await response.json();
        setTimesheetEntries(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchCurrentUser();
    fetchTimesheetEntries();
  }, []);

  const handleDelete = async (id: number) => {
    if (!currentUser || currentUser.role !== "supervisor") {
      alert("Only supervisors can delete entries.");
      return;
    }

    const entryToDelete = timesheetEntries.find(entry => entry.id === id);
    if (!entryToDelete) {
      alert("Entry not found.");
      return;
    }

    if (entryToDelete.supervisorId !== currentUser.id) {
      alert("You can only delete your own entries.");
      return;
    }

    try {
      const response = await fetch(`/api/timesheets-api/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error(`Failed to delete entry: ${response.status}`);
      }

      // Remove the deleted entry from the state
      setTimesheetEntries(prev => prev.filter(entry => entry.id !== id));
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "system-ui" }}>
      <h1>Supervisor Timesheet Management</h1>
      {timesheetEntries.length === 0 ? (
        <p>No timesheet entries found.</p>
      ) : (
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr style={{ borderBottom: "1px solid #ccc" }}>
              <th style={{ textAlign: "left", padding: "10px" }}>Date</th>
              <th style={{ textAlign: "left", padding: "10px" }}>Hours</th>
              <th style={{ textAlign: "left", padding: "10px" }}>Associate ID</th>
              <th style={{ textAlign: "left", padding: "10px" }}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {timesheetEntries.map(entry => (
              <tr key={entry.id} style={{ borderBottom: "1px solid #eee" }}>
                <td style={{ padding: "10px" }}>{entry.date}</td>
                <td style={{ padding: "10px" }}>{entry.hours}</td>
                <td style={{ padding: "10px" }}>{entry.associateId}</td>
                <td style={{ padding: "10px" }}>
                  <button
                    onClick={() => handleDelete(entry.id)}
                    style={{
                      backgroundColor: "#dc3545",
                      color: "white",
                      border: "none",
                      padding: "5px 10px",
                      borderRadius: "4px",
                      cursor: "pointer"
                    }}
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

interface Checkout {
  id: number;
  item: string;
  borrower: string;
  checkoutDate: string;
  dueDate: string;
}

export function SupervisorDeletePanel() {
  const [checkouts, setCheckouts] = useState<Checkout[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchCheckouts();
  }, []);

  const fetchCheckouts = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/checkouts-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setCheckouts(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/checkouts-api/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error(`Failed to delete: ${response.status} ${response.statusText}`);
      }
      // Refresh the list after deletion
      await fetchCheckouts();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>
        Error: {error}
      </div>
    );
  }

  if (checkouts.length === 0) {
    return (
      <div style={{ textAlign: 'center', padding: '20px' }}>
        No checkout records found.
      </div>
    );
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Supervisor Delete Panel</h1>
      <p style={{ textAlign: 'center', marginBottom: '20px' }}>Manage checkout records</p>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        {checkouts.map((checkout) => (
          <div 
            key={checkout.id} 
            style={{ 
              border: '1px solid #ccc', 
              borderRadius: '8px', 
              padding: '15px', 
              display: 'flex', 
              justifyContent: 'space-between', 
              alignItems: 'center'
            }}
          >
            <div>
              <strong>{checkout.item}</strong><br />
              Borrower: {checkout.borrower}<br />
              Checkout Date: {checkout.checkoutDate}<br />
              Due Date: {checkout.dueDate}
            </div>
            <button 
              onClick={() => handleDelete(checkout.id)}
              style={{ 
                backgroundColor: '#ff4d4d', 
                color: 'white', 
                border: 'none', 
                borderRadius: '4px', 
                padding: '8px 12px', 
                cursor: 'pointer'
              }}
            >
              Delete
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

