import { useEffect, useState } from "react";

interface Exercise {
  id: string;
  name: string;
  sets: number;
  reps: number;
}

interface Workout {
  id: string;
  clientId: string;
  date: string;
  duration: number;
  exercises: Exercise[];
}

interface Client {
  id: string;
  name: string;
  email: string;
}

export function WorkoutLog() {
  const [clients, setClients] = useState<Client[]>([]);
  const [workouts, setWorkouts] = useState<Workout[]>([]);
  const [selectedClient, setSelectedClient] = useState<string>("");
  const [date, setDate] = useState<string>("");
  const [duration, setDuration] = useState<number>(0);
  const [exercises, setExercises] = useState<Exercise[]>([
    { id: "", name: "", sets: 0, reps: 0 }
  ]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string>("");

  useEffect(() => {
    const fetchClients = async () => {
      try {
        const response = await fetch("/api/workouts-api/");
        if (!response.ok) throw new Error("Failed to fetch clients");
        const data = await response.json();
        setClients(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Unknown error");
      } finally {
        setLoading(false);
      }
    };

    fetchClients();
  }, []);

  const handleAddExercise = () => {
    setExercises([...exercises, { id: "", name: "", sets: 0, reps: 0 }]);
  };

  const handleExerciseChange = (index: number, field: keyof Exercise, value: string | number) => {
    const updatedExercises = [...exercises];
    updatedExercises[index] = { ...updatedExercises[index], [field]: value };
    setExercises(updatedExercises);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedClient || !date || duration <= 0) {
      setError("Please fill in all required fields.");
      return;
    }

    try {
      const newWorkout: Omit<Workout, "id"> = {
        clientId: selectedClient,
        date,
        duration,
        exercises
      };

      const response = await fetch("/api/workouts-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newWorkout)
      });

      if (!response.ok) throw new Error("Failed to create workout");

      // Reset form
      setSelectedClient("");
      setDate("");
      setDuration(0);
      setExercises([{ id: "", name: "", sets: 0, reps: 0 }]);

      // Reload data
      const response2 = await fetch("/api/workouts-api/");
      if (response2.ok) {
        const data = await response2.json();
        setWorkouts(data);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unknown error");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Log Workout Session</h1>

      {error && <div style={{ color: "red", marginBottom: "10px" }}>{error}</div>}

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        <div>
          <label style={{ display: "block", marginBottom: "5px" }}>Client:</label>
          <select
            value={selectedClient}
            onChange={(e) => setSelectedClient(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="">Select a client</option>
            {clients.map(client => (
              <option key={client.id} value={client.id}>{client.name}</option>
            ))}
          </select>
        </div>

        <div>
          <label style={{ display: "block", marginBottom: "5px" }}>Date:</label>
          <input
            type="date"
            value={date}
            onChange={(e) => setDate(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>

        <div>
          <label style={{ display: "block", marginBottom: "5px" }}>Duration (minutes):</label>
          <input
            type="number"
            min="1"
            value={duration}
            onChange={(e) => setDuration(Number(e.target.value))}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>

        <div>
          <label style={{ display: "block", marginBottom: "5px" }}>Exercises:</label>
          {exercises.map((exercise, index) => (
            <div key={index} style={{ display: "flex", gap: "10px", marginBottom: "10px" }}>
              <input
                type="text"
                placeholder="Exercise name"
                value={exercise.name}
                onChange={(e) => handleExerciseChange(index, "name", e.target.value)}
                style={{ flex: 1, padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              />
              <input
                type="number"
                min="0"
                placeholder="Sets"
                value={exercise.sets}
                onChange={(e) => handleExerciseChange(index, "sets", Number(e.target.value))}
                style={{ width: "80px", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              />
              <input
                type="number"
                min="0"
                placeholder="Reps"
                value={exercise.reps}
                onChange={(e) => handleExerciseChange(index, "reps", Number(e.target.value))}
                style={{ width: "80px", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
              />
            </div>
          ))}
          <button
            type="button"
            onClick={handleAddExercise}
            style={{ padding: "8px 12px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
          >
            Add Exercise
          </button>
        </div>

        <button
          type="submit"
          style={{ padding: "10px", backgroundColor: "#28a745", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
        >
          Log Workout
        </button>
      </form>
    </div>
  );
}

