import { useEffect, useState } from "react";

export function OwnerOnlyExportPanel() {
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Component mounts, but we don't need to fetch data for this panel
    // It just needs to trigger the export
    setLoading(false);
  }, []);

  const handleDownloadCSV = async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch('/api/export-service/export/csv', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(`Failed to export: ${response.status} ${response.statusText}`);
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'appointment-history.csv';
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      maxWidth: '600px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
    }}>
      <h1 style={{
        fontSize: '24px',
        fontWeight: 'bold',
        marginBottom: '20px',
        textAlign: 'center',
      }}>
        Owner-Only Export Panel
      </h1>

      <p style={{
        fontSize: '16px',
        marginBottom: '20px',
        textAlign: 'center',
      }}>
        Download a raw CSV of all appointment history.
      </p>

      <button
        onClick={handleDownloadCSV}
        disabled={loading}
        style={{
          backgroundColor: '#007bff',
          color: 'white',
          border: 'none',
          borderRadius: '4px',
          padding: '10px 20px',
          fontSize: '16px',
          cursor: loading ? 'not-allowed' : 'pointer',
          transition: 'background-color 0.2s',
        }}
      >
        {loading ? 'Exporting...' : 'Download CSV'}
      </button>

      {error && (
        <p style={{
          color: 'red',
          marginTop: '20px',
          textAlign: 'center',
        }}>
          {error}
        </p>
      )}
    </div>
  );
}

