  const [sessions, setSessions] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchSessions();
  }, []);

  const fetchSessions = async () => {
    try {
      const response = await fetch('/api/sessions-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch sessions: ${response.status}`);
      }
      const data = await response.json();
      setSessions(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleDownloadCSV = () => {
    // Create CSV content
    const headers = ['ID', 'Student Name', 'Session Date', 'Duration', 'Status'];
    const csvContent = [
      headers.join(','),
      ...sessions.map(session => [
        session.id,
        session.studentName || '',
        session.sessionDate || '',
        session.duration || '',
        session.status || ''
      ].join(','))
    ].join('\n');

    // Create and download file
    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'tutor-sessions.csv';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.URL.revokeObjectURL(url);
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Owner-Only Export Panel</h1>
      <p style={{ textAlign: 'center' }}>Download all session records as CSV</p>

      <div style={{ textAlign: 'center', margin: '20px 0' }}>
        <button 
          onClick={handleDownloadCSV}
          style={{ 
            backgroundColor: '#007bff', 
            color: 'white', 
            border: 'none', 
            padding: '10px 20px', 
            borderRadius: '5px', 
            cursor: 'pointer' 
          }}
        >
          Download CSV
        </button>
      </div>

      <div style={{ marginTop: '20px' }}>
        <h2>Session Records</h2>
        {sessions.length === 0 ? (
          <p>No session records found.</p>
        ) : (
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: '1px solid #ddd' }}>
                <th style={{ padding: '8px', textAlign: 'left' }}>ID</th>
                <th style={{ padding: '8px', textAlign: 'left' }}>Student Name</th>
                <th style={{ padding: '8px', textAlign: 'left' }}>Session Date</th>
                <th style={{ padding: '8px', textAlign: 'left' }}>Duration</th>
                <th style={{ padding: '8px', textAlign: 'left' }}>Status</th>
              </tr>
            </thead>
            <tbody>
              {sessions.map(session => (
                <tr key={session.id} style={{ borderBottom: '1px solid #ddd' }}>
                  <td style={{ padding: '8px' }}>{session.id}</td>
                  <td style={{ padding: '8px' }}>{session.studentName || '-'}</td>
                  <td style={{ padding: '8px' }}>{session.sessionDate || '-'}</td>
                  <td style={{ padding: '8px' }}>{session.duration || '-'}</td>
                  <td style={{ padding: '8px' }}>{session.status || '-'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

import { FC, useEffect, useState } from "react";

interface Submission {
  id: string;
  title: string;
  authorId: string;
}

interface Export {
  id: string;
  submissionId: string;
  status: string;
}

export function ExportHistoryGuard() {
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [exports, setExports] = useState<Export[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentUserId, setCurrentUserId] = useState<string | null>(null);

  useEffect(() => {
    const fetchUserData = async () => {
      try {
        const userResponse = await fetch('/api/user');
        if (!userResponse.ok) throw new Error('Failed to fetch user data');
        const userData = await userResponse.json();
        setCurrentUserId(userData.id);
      } catch (err) {
        setError('Failed to load user data');
        setLoading(false);
      }
    };

    const fetchSubmissions = async () => {
      try {
        const response = await fetch('/api/submissions-api/submissions');
        if (!response.ok) throw new Error('Failed to fetch submissions');
        const data = await response.json();
        setSubmissions(data);
      } catch (err) {
        setError('Failed to load submissions');
      } finally {
        setLoading(false);
      }
    };

    const fetchExports = async () => {
      try {
        const response = await fetch('/api/submissions-api/exports');
        if (!response.ok) throw new Error('Failed to fetch exports');
        const data = await response.json();
        setExports(data);
      } catch (err) {
        setError('Failed to load exports');
      }
    };

    fetchUserData();
    fetchSubmissions();
    fetchExports();
  }, []);

  const handleExport = async (submissionId: string) => {
    try {
      const response = await fetch(`/api/export-guard-service/export/${submissionId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      });

      if (!response.ok) throw new Error('Export failed');

      // Refresh data after successful export
      const submissionsResponse = await fetch('/api/submissions-api/submissions');
      const exportsResponse = await fetch('/api/submissions-api/exports');

      if (submissionsResponse.ok && exportsResponse.ok) {
        const submissionsData = await submissionsResponse.json();
        const exportsData = await exportsResponse.json();

        setSubmissions(submissionsData);
        setExports(exportsData);
      }
    } catch (err) {
      setError('Export failed');
    }
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;

  if (error) return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Export History</h1>

      {submissions.length === 0 ? (
        <p>No submissions found.</p>
      ) : (
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ borderBottom: '1px solid #ccc' }}>
              <th style={{ textAlign: 'left', padding: '10px' }}>Title</th>
              <th style={{ textAlign: 'left', padding: '10px' }}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {submissions.map((submission) => {
              const hasExport = exports.some(e => e.submissionId === submission.id);
              const canExport = currentUserId === submission.authorId;

              return (
                <tr key={submission.id} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '10px' }}>{submission.title}</td>
                  <td style={{ padding: '10px' }}>
                    {canExport && !hasExport ? (
                      <button 
                        onClick={() => handleExport(submission.id)}
                        style={{ 
                          backgroundColor: '#007bff', 
                          color: 'white', 
                          border: 'none', 
                          borderRadius: '4px', 
                          padding: '8px 12px', 
                          cursor: 'pointer' 
                        }}
                      >
                        Export
                      </button>
                    ) : null}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

interface Batch {
  id: number;
  cheeseType: string;
  startDate: string;
  endDate?: string;
  status: 'aging' | 'completed' | 'failed';
}

export function BatchLogForm() {
  const [batches, setBatches] = useState<Batch[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    cheeseType: '',
    startDate: '',
    status: 'aging' as 'aging' | 'completed' | 'failed',
  });
  const [editingId, setEditingId] = useState<number | null>(null);

  useEffect(() => {
    fetchBatches();
  }, []);

  const fetchBatches = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/aging-batch-api/');
      if (!response.ok) throw new Error('Failed to fetch batches');
      const data = await response.json();
      setBatches(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const url = editingId 
        ? `/api/aging-batch-api/${editingId}`
        : '/api/aging-batch-api/';
      const method = editingId ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });

      if (!response.ok) throw new Error('Failed to save batch');

      fetchBatches();
      resetForm();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleEdit = (batch: Batch) => {
    setFormData({
      cheeseType: batch.cheeseType,
      startDate: batch.startDate,
      status: batch.status,
    });
    setEditingId(batch.id);
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/aging-batch-api/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) throw new Error('Failed to delete batch');
      fetchBatches();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const resetForm = () => {
    setFormData({
      cheeseType: '',
      startDate: '',
      status: 'aging',
    });
    setEditingId(null);
  };

  if (loading) return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  if (error) return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Batch Log Form</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: '30px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>Cheese Type:</label>
          <input
            type="text"
            value={formData.cheeseType}
            onChange={(e) => setFormData({...formData, cheeseType: e.target.value})}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>Start Date:</label>
          <input
            type="date"
            value={formData.startDate}
            onChange={(e) => setFormData({...formData, startDate: e.target.value})}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
            required
          />
        </div>

        <div style={{ marginBottom: '15px' }}>
          <label style={{ display: 'block', marginBottom: '5px' }}>Status:</label>
          <select
            value={formData.status}
            onChange={(e) => setFormData({...formData, status: e.target.value as any})}
            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ddd' }}
          >
            <option value="aging">Aging</option>
            <option value="completed">Completed</option>
            <option value="failed">Failed</option>
          </select>
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: '#007bff', 
            color: 'white', 
            border: 'none', 
            padding: '10px 20px', 
            borderRadius: '4px', 
            cursor: 'pointer' 
          }}
        >
          {editingId ? 'Update Batch' : 'Add Batch'}
        </button>

        {editingId && (
          <button 
            type="button" 
            onClick={resetForm}
            style={{ 
              backgroundColor: '#6c757d', 
              color: 'white', 
              border: 'none', 
              padding: '10px 20px', 
              borderRadius: '4px', 
              cursor: 'pointer', 
              marginLeft: '10px' 
            }}
          >
            Cancel Edit
          </button>
        )}
      </form>

      <h2 style={{ textAlign: 'center' }}>Aging Batches</h2>

      {batches.length === 0 ? (
        <p style={{ textAlign: 'center', fontStyle: 'italic' }}>No batches found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {batches.map(batch => (
            <div 
              key={batch.id} 
              style={{ 
                border: '1px solid #ccc', 
                borderRadius: '8px', 
                padding: '15px', 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center' 
              }}
            >
              <div>
                <strong>{batch.cheeseType}</strong> - {batch.startDate}
                <br />
                Status: {batch.status}
              </div>
              <div>
                <button 
                  onClick={() => handleEdit(batch)}
                  style={{ 
                    backgroundColor: '#17a2b8', 
                    color: 'white', 
                    border: 'none', 
                    padding: '5px 10px', 
                    borderRadius: '4px', 
                    cursor: 'pointer', 
                    marginRight: '5px' 
                  }}
                >
                  Edit
                </button>
                <button 
                  onClick={() => handleDelete(batch.id)}
                  style={{ 
                    backgroundColor: '#dc3545', 
                    color: 'white', 
                    border: 'none', 
                    padding: '5px 10px', 
                    borderRadius: '4px', 
                    cursor: 'pointer' 
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

