  name: string;
}

export function CampaignComposer() {
  const [subscribers, setSubscribers] = useState<Subscriber[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [newSubscriber, setNewSubscriber] = useState({
    email: "",
    name: ""
  });

  useEffect(() => {
    fetchSubscribers();
  }, []);

  const fetchSubscribers = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/mailing-list-engine/subscribers");
      if (!response.ok) {
        throw new Error(`Failed to fetch subscribers: ${response.status}`);
      }
      const data = await response.json();
      setSubscribers(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleAddSubscriber = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("/api/mailing-list-engine/subscribers", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newSubscriber)
      });
      if (!response.ok) {
        throw new Error(`Failed to add subscriber: ${response.status}`);
      }
      setNewSubscriber({ email: "", name: "" });
      fetchSubscribers();
