import { useEffect, useState } from "react";

interface Order {
  id: number;
  customerName: string;
  cakeType: string;
  orderDate: string;
  status: string;
}

export function OrderList() {
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [currentUserRole, setCurrentUserRole] = useState<"customer" | "supervisor">("customer");

  useEffect(() => {
    fetchOrders();
    // Mock role assignment - in real app this would come from auth context
    setCurrentUserRole("supervisor");
  }, []);

  const fetchOrders = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/orders-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch orders: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setOrders(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/orders-api/${id}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error(`Failed to delete order: ${response.status} ${response.statusText}`);
      }
      // Refresh the list after deletion
      fetchOrders();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ color: 'red', textAlign: 'center', padding: '20px' }}>{error}</div>;
  }

  if (orders.length === 0) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>No open orders found.</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Open Orders</h1>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        {orders.map(order => (
          <div 
            key={order.id} 
            style={{ 
              border: '1px solid #ccc', 
              borderRadius: '8px', 
              padding: '15px', 
              display: 'flex', 
              justifyContent: 'space-between', 
              alignItems: 'center'
            }}
          >
            <div>
              <strong>{order.customerName}</strong> - {order.cakeType}
              <br />
              <small>{new Date(order.orderDate).toLocaleDateString()} - {order.status}</small>
            </div>
            {currentUserRole === "supervisor" && (
              <button 
                onClick={() => handleDelete(order.id)}
                style={{ 
                  backgroundColor: '#ff4d4d', 
                  color: 'white', 
                  border: 'none', 
                  borderRadius: '4px', 
                  padding: '8px 12px', 
                  cursor: 'pointer'
                }}
              >
                Delete
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

import { FC, useEffect, useState } from "react";

interface AttendanceRecord {
  id: number;
  supervisorId: number;
  date: string;
  status: string;
}

export function SupervisorDeletionGuard() {
  const [records, setRecords] = useState<AttendanceRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [supervisorId, setSupervisorId] = useState<number>(1); // Example supervisor ID

  useEffect(() => {
    fetchRecords();
  }, []);

  const fetchRecords = async () => {
    try {
      const response = await fetch(`/api/attendance-records-api/`);
      if (!response.ok) {
        throw new Error(`Failed to fetch records: ${response.status}`);
      }
      const data = await response.json();
      setRecords(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleDelete = async (id: number) => {
    try {
      // Check if the record belongs to the current supervisor
      const record = records.find(r => r.id === id);
      if (!record) return;

      if (record.supervisorId === supervisorId) {
        alert("You cannot delete your own attendance record.");
        return;
      }

      const response = await fetch(`/api/attendance-records-api/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error(`Failed to delete record: ${response.status}`);
      }

      // Refresh the list after successful deletion
      fetchRecords();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center" }}>{error}</div>;

  if (records.length === 0) {
    return <div style={{ textAlign: "center" }}>No attendance records found.</div>;
  }

  return (
    <div style={{ maxWidth: 800, margin: "0 auto", padding: 20, fontFamily: "system-ui" }}>
      <h2>Attendance Records</h2>
      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead>
          <tr style={{ borderBottom: "1px solid #ccc" }}>
            <th style={{ textAlign: "left", padding: 10 }}>Date</th>
            <th style={{ textAlign: "left", padding: 10 }}>Status</th>
            <th style={{ textAlign: "left", padding: 10 }}>Actions</th>
          </tr>
        </thead>
        <tbody>
          {records.map(record => (
            <tr key={record.id} style={{ borderBottom: "1px solid #eee" }}>
              <td style={{ padding: 10 }}>{record.date}</td>
              <td style={{ padding: 10 }}>{record.status}</td>
              <td style={{ padding: 10 }}>
                <button 
                  onClick={() => handleDelete(record.id)}
                  style={{ 
                    backgroundColor: "#dc3545", 
                    color: "white", 
                    border: "none", 
                    padding: "5px 10px", 
                    borderRadius: 4, 
                    cursor: "pointer" 
                  }}
                >
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import { useEffect, useState } from "react";

interface Plot {
  id: number;
  name: string;
  size: string;
  location: string;
}

interface Reservation {
  id: number;
  plotId: number;
  memberId: number;
  startDate: string;
  endDate: string;
}

export function PlotReservationView() {
  const [plots, setPlots] = useState<Plot[]>([]);
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedPlotId, setSelectedPlotId] = useState<number | null>(null);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [plotsResponse, reservationsResponse] = await Promise.all([
          fetch("/api/reservations-api/"),
          fetch("/api/reservations-api/"),
        ]);

        if (!plotsResponse.ok || !reservationsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const plotsData = await plotsResponse.json();
        const reservationsData = await reservationsResponse.json();

        setPlots(plotsData);
        setReservations(reservationsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleReserve = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedPlotId || !startDate || !endDate) return;

    try {
      const response = await fetch("/api/reservations-api/", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          plotId: selectedPlotId,
          memberId: 1, // Assuming current member ID is 1
          startDate,
          endDate,
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to reserve plot");
      }

      // Refresh data after successful reservation
      const [plotsResponse, reservationsResponse] = await Promise.all([
        fetch("/api/reservations-api/"),
        fetch("/api/reservations-api/"),
      ]);

      if (!plotsResponse.ok || !reservationsResponse.ok) {
        throw new Error("Failed to refresh data");
      }

      const plotsData = await plotsResponse.json();
      const reservationsData = await reservationsResponse.json();

      setPlots(plotsData);
      setReservations(reservationsData);

      // Reset form
      setSelectedPlotId(null);
      setStartDate("");
      setEndDate("");
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  const availablePlots = plots.filter(plot => 
    !reservations.some(res => res.plotId === plot.id)
  );

  return (
    <div style={{
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
    }}>
      <h1 style={{ textAlign: "center" }}>Plot Reservation</h1>

      <div style={{ marginBottom: "30px" }}>
        <h2>Available Plots</h2>
        {availablePlots.length === 0 ? (
          <p>No plots available for reservation.</p>
        ) : (
          <div style={{ display: "flex", flexWrap: "wrap", gap: "15px" }}>
            {availablePlots.map(plot => (
              <div 
                key={plot.id} 
                style={{
                  border: "1px solid #ccc",
                  borderRadius: "8px",
                  padding: "15px",
                  width: "200px",
                  boxSizing: "border-box",
                }}
              >
                <h3>{plot.name}</h3>
                <p>Size: {plot.size}</p>
                <p>Location: {plot.location}</p>
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "20px" }}>
        <h2>Reserve a Plot</h2>
        <form onSubmit={handleReserve}>
          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="plotSelect">Select Plot:</label>
            <select
              id="plotSelect"
              value={selectedPlotId ?? ""}
              onChange={(e) => setSelectedPlotId(Number(e.target.value))}
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            >
              <option value="">Choose a plot</option>
              {availablePlots.map(plot => (
                <option key={plot.id} value={plot.id}>{plot.name}</option>
              ))}
            </select>
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="startDate">Start Date:</label>
            <input
              type="date"
              id="startDate"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            />
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="endDate">End Date:</label>
            <input
              type="date"
              id="endDate"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            />
          </div>

          <button 
            type="submit" 
            style={{
              backgroundColor: "#007bff",
              color: "white",
              border: "none",
              borderRadius: "4px",
              padding: "10px 20px",
              cursor: "pointer",
            }}
          >
            Reserve Plot
          </button>
        </form>
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";

export function OwnerExportPanel() {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [reservations, setReservations] = useState<any[]>([]);

  useEffect(() => {
    async function fetchReservations() {
      try {
        const response = await fetch('/api/reservations-api/');
        if (!response.ok) {
          throw new Error(`Failed to fetch reservations: ${response.status} ${response.statusText}`);
        }
        const data = await response.json();
        setReservations(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    }

    fetchReservations();
  }, []);

  const handleExport = async () => {
    try {
      const response = await fetch('/api/export-service/export', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(`Export failed: ${response.status} ${response.statusText}`);
      }

      // Get the CSV content from the response
      const csvContent = await response.text();

      // Create a blob and download link
      const blob = new Blob([csvContent], { type: 'text/csv' });
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'reservations-export.csv';
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred during export');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Owner Export Panel</h1>
      <p style={{ textAlign: 'center' }}>Download a CSV of all reservations</p>

      <div style={{ marginBottom: '20px', textAlign: 'center' }}>
        <button 
          onClick={handleExport}
          style={{ 
            backgroundColor: '#4CAF50', 
            color: 'white', 
            border: 'none', 
            padding: '10px 20px', 
            borderRadius: '4px', 
            cursor: 'pointer', 
            fontSize: '16px'
          }}
        >
          Export All Reservations to CSV
        </button>
      </div>

      <div style={{ 
        border: '1px solid #ccc', 
        borderRadius: '4px', 
        padding: '10px', 
        overflowX: 'auto'
      }}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ backgroundColor: '#f2f2f2' }}>
              <th style={{ border: '1px solid #ddd', padding: '8px', textAlign: 'left' }}>ID</th>
              <th style={{ border: '1px solid #ddd', padding: '8px', textAlign: 'left' }}>Plot ID</th>
              <th style={{ border: '1px solid #ddd', padding: '8px', textAlign: 'left' }}>Start Date</th>
              <th style={{ border: '1px solid #ddd', padding: '8px', textAlign: 'left' }}>End Date</th>
              <th style={{ border: '1px solid #ddd', padding: '8px', textAlign: 'left' }}>User Email</th>
            </tr>
          </thead>
          <tbody>
            {reservations.length === 0 ? (
              <tr>
                <td colSpan={5} style={{ border: '1px solid #ddd', padding: '8px', textAlign: 'center' }}>
                  No reservations found.
                </td>
              </tr>
            ) : (
              reservations.map((reservation) => (
                <tr key={reservation.id}>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{reservation.id}</td>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{reservation.plotId}</td>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{new Date(reservation.startDate).toLocaleDateString()}</td>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{new Date(reservation.endDate).toLocaleDateString()}</td>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{reservation.userEmail}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { FC, useEffect, useState } from "react";

interface TimesheetEntry {
  id?: number;
  date: string;
  client: string;
  hours: number;
}

export function TimesheetEntryForm() {
  const [entries, setEntries] = useState<TimesheetEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    date: "",
    client: "",
    hours: ""
  });

  useEffect(() => {
    fetchEntries();
  }, []);

  const fetchEntries = async () => {
    try {
      const response = await fetch("/api/timesheets-api/");
      if (!response.ok) throw new Error("Failed to fetch timesheet entries");
      const data = await response.json();
      setEntries(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const newEntry: TimesheetEntry = {
      date: formData.date,
      client: formData.client,
      hours: Number(formData.hours)
    };

    try {
      const response = await fetch("/api/timesheets-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newEntry)
      });

      if (!response.ok) throw new Error("Failed to create timesheet entry");

      // Reset form
      setFormData({ date: "", client: "", hours: "" });

      // Refresh entries
      await fetchEntries();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "600px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Timesheet Entry</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="date" style={{ display: "block", marginBottom: "5px" }}>Date:</label>
          <input
            type="date"
            id="date"
            name="date"
            value={formData.date}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="client" style={{ display: "block", marginBottom: "5px" }}>Client:</label>
          <input
            type="text"
            id="client"
            name="client"
            value={formData.client}
            onChange={handleChange}
            required
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="hours" style={{ display: "block", marginBottom: "5px" }}>Hours:</label>
          <input
            type="number"
            id="hours"
            name="hours"
            value={formData.hours}
            onChange={handleChange}
            required
            min="0"
            step="0.25"
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            border: "none", 
            padding: "10px 20px", 
            borderRadius: "4px", 
            cursor: "pointer", 
            fontSize: "16px" 
          }}
        >
          Submit Entry
        </button>
      </form>

      <h2 style={{ textAlign: "center" }}>Recent Entries</h2>

      {entries.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No entries found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {entries.map(entry => (
            <div 
              key={entry.id} 
              style={{ 
                padding: "15px", 
                border: "1px solid #ccc", 
                borderRadius: "8px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center" 
              }}
            >
              <div>
                <strong>{entry.date}</strong> - {entry.client}: {entry.hours} hours
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

