import { useEffect, useState } from "react";

export function OwnerOnlyExportPanel() {
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await fetch('/api/usage-api');
        if (!response.ok) {
          throw new Error(`Failed to fetch data: ${response.status} ${response.statusText}`);
        }
        const result = await response.json();
        setData(result);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleDownload = () => {
    // Convert data to CSV format
    const headers = ['Member ID', 'Usage (kWh)', 'Date'];
    const csvContent = [
      headers.join(','),
      ...data.map(row => `${row.memberId},${row.usageKwh},${row.date}`)
    ].join('\n');

    // Create a Blob and download link
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'usage-data.csv');
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui' }}>
      <h1 style={{ textAlign: 'center' }}>Owner-Only Export Panel</h1>
      <p style={{ textAlign: 'center' }}>Download the full dataset as CSV</p>

      <div style={{ textAlign: 'center', marginBottom: '20px' }}>
        <button 
          onClick={handleDownload}
          style={{ 
            backgroundColor: '#007bff', 
            color: 'white', 
            border: 'none', 
            padding: '10px 20px', 
            borderRadius: '5px', 
            cursor: 'pointer' 
          }}
        >
          Download CSV
        </button>
      </div>

      <div style={{ 
        border: '1px solid #ccc', 
        borderRadius: '5px', 
        padding: '10px', 
        overflowX: 'auto' 
      }}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ backgroundColor: '#f2f2f2' }}>
              <th style={{ border: '1px solid #ddd', padding: '8px' }}>Member ID</th>
              <th style={{ border: '1px solid #ddd', padding: '8px' }}>Usage (kWh)</th>
              <th style={{ border: '1px solid #ddd', padding: '8px' }}>Date</th>
            </tr>
          </thead>
          <tbody>
            {data.length === 0 ? (
              <tr>
                <td colSpan={3} style={{ textAlign: 'center', padding: '10px' }}>
                  No data available
                </td>
              </tr>
            ) : (
              data.map((row, index) => (
                <tr key={index}>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{row.memberId}</td>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{row.usageKwh}</td>
                  <td style={{ border: '1px solid #ddd', padding: '8px' }}>{row.date}</td>
                </tr>
              ))
