          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="description" style={{ display: "block", marginBottom: "5px" }}>Description:</label>
          <textarea
            id="description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd", boxSizing: "border-box" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="distance" style={{ display: "block", marginBottom: "5px" }}>Distance (km):</label>
          <input
            id="distance"
            type="number"
            value={distance}
            onChange={(e) => setDistance(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="elevation" style={{ display: "block", marginBottom: "5px" }}>Elevation (m):</label>
          <input
            id="elevation"
            type="number"
            value={elevation}
            onChange={(e) => setElevation(e.target.value)}
            style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ddd" }}
            required
          />
        </div>

        <button 
          type="submit" 
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            border: "none", 
            padding: "10px 20px", 
            borderRadius: "4px", 
            cursor: "pointer", 
            fontSize: "16px" 
          }}
        >
          Add Route
        </button>
      </form>

      <h2 style={{ textAlign: "center" }}>All Routes</h2>

      {routes.length === 0 ? (
        <p style={{ textAlign: "center", fontStyle: "italic" }}>No routes logged yet.</p>
