                <th style={{ padding: '10px', textAlign: 'left' }}>Name</th>
                <th style={{ padding: '10px', textAlign: 'left' }}>Distance</th>
                <th style={{ padding: '10px', textAlign: 'left' }}>Duration</th>
              </tr>
            </thead>
            <tbody>
              {routes.map(route => (
                <tr key={route.id} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '10px' }}>{route.id}</td>
                  <td style={{ padding: '10px' }}>{route.name}</td>
