import { useEffect, useState } from "react";

interface Schedule {
  id: string;
  name: string;
  sourcePath: string;
  destinationPath: string;
  scheduleExpression: string;
  isEnabled: boolean;
}

export function BackupConfigurationUi() {
  const [schedules, setSchedules] = useState<Schedule[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    name: "",
    sourcePath: "",
    destinationPath: "",
    scheduleExpression: "",
    isEnabled: true
  });

  const [editingId, setEditingId] = useState<string | null>(null);

  useEffect(() => {
    fetchSchedules();
  }, []);

  const fetchSchedules = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/backup-scheduler/status');
      if (!response.ok) throw new Error('Failed to fetch schedules');
      const data = await response.json();
      setSchedules(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value, type } = e.target as HTMLInputElement | HTMLTextAreaElement;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? (e.target as HTMLInputElement).checked : value
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = editingId 
        ? await fetch(`/api/backup-scheduler/schedule/${editingId}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(formData)
          })
        : await fetch('/api/backup-scheduler/schedule', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(formData)
          });

      if (!response.ok) throw new Error('Failed to save schedule');

      // Reset form and refetch data
      setFormData({
        name: "",
        sourcePath: "",
        destinationPath: "",
        scheduleExpression: "",
        isEnabled: true
      });
      setEditingId(null);
      fetchSchedules();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const handleEdit = (schedule: Schedule) => {
    setFormData({
      name: schedule.name,
      sourcePath: schedule.sourcePath,
      destinationPath: schedule.destinationPath,
      scheduleExpression: schedule.scheduleExpression,
      isEnabled: schedule.isEnabled
    });
    setEditingId(schedule.id);
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/backup-scheduler/schedule/${id}`, {
        method: 'DELETE'
      });
      if (!response.ok) throw new Error('Failed to delete schedule');
      fetchSchedules();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  const containerStyle: React.CSSProperties = {
    maxWidth: '800px',
    margin: '0 auto',
    padding: '20px',
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif'
  };

  const cardStyle: React.CSSProperties = {
    border: '1px solid #ddd',
    borderRadius: '8px',
    padding: '16px',
    marginBottom: '16px',
    backgroundColor: '#f9f9f9'
  };

  const inputStyle: React.CSSProperties = {
    width: '100%',
    padding: '8px',
    marginBottom: '12px',
    borderRadius: '4px',
    border: '1px solid #ccc'
  };

  const buttonStyle: React.CSSProperties = {
    backgroundColor: '#007bff',
    color: 'white',
    border: 'none',
    padding: '8px 16px',
    borderRadius: '4px',
    cursor: 'pointer',
    marginRight: '8px'
  };

  const buttonGroupStyle: React.CSSProperties = {
    display: 'flex',
    flexWrap: 'wrap',
    gap: '8px'
  };

  if (loading) return <div style={containerStyle}>Loading...</div>;

  if (error) return (
    <div style={containerStyle}>
      <h2>Error</h2>
      <p>{error}</p>
    </div>
  );

  return (
    <div style={containerStyle}>
      <h1>Backup Configuration</h1>

      <form onSubmit={handleSubmit} style={cardStyle}>
        <h2>{editingId ? 'Edit Schedule' : 'Create New Schedule'}</h2>

        <input
          type="text"
          name="name"
          placeholder="Schedule Name"
          value={formData.name}
          onChange={handleInputChange}
          style={inputStyle}
        />

        <input
          type="text"
          name="sourcePath"
          placeholder="Source Path"
          value={formData.sourcePath}
          onChange={handleInputChange}
          style={inputStyle}
        />

        <input
          type="text"
          name="destinationPath"
          placeholder="Destination Path"
          value={formData.destinationPath}
          onChange={handleInputChange}
          style={inputStyle}
        />

        <input
          type="text"
          name="scheduleExpression"
          placeholder="Cron Expression"
          value={formData.scheduleExpression}
          onChange={handleInputChange}
          style={inputStyle}
        />

        <label>
          <input
            type="checkbox"
            name="isEnabled"
            checked={formData.isEnabled}
            onChange={handleInputChange}
          /> Enable Schedule
        </label>

        <button type="submit" style={buttonStyle}>Save Schedule</button>
      </form>

      <h2>Saved Schedules</h2>

      {schedules.length === 0 ? (
        <p>No schedules found.</p>
      ) : (
        <div>
          {schedules.map(schedule => (
            <div key={schedule.id} style={cardStyle}>
              <h3>{schedule.name}</h3>
              <p><strong>Source:</strong> {schedule.sourcePath}</p>
              <p><strong>Destination:</strong> {schedule.destinationPath}</p>
              <p><strong>Schedule:</strong> {schedule.scheduleExpression}</p>
              <p><strong>Status:</strong> {schedule.isEnabled ? 'Enabled' : 'Disabled'}</p>

              <div style={buttonGroupStyle}>
                <button onClick={() => handleEdit(schedule)} style={buttonStyle}>Edit</button>
                <button onClick={() => handleDelete(schedule.id)} style={buttonStyle}>Delete</button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

interface Page {
  id: string;
  title: string;
  content: string;
}

export function PageEditor() {
  const [pages, setPages] = useState<Page[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [editingId, setEditingId] = useState<string | null>(null);

  useEffect(() => {
    fetchPages();
  }, []);

  const fetchPages = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/docs-api/pages");
      if (!response.ok) throw new Error("Failed to fetch pages");
      const data = await response.json();
      setPages(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const method = editingId ? "PUT" : "POST";
      const url = editingId 
        ? `/api/docs-api/pages/${editingId}`
        : "/api/docs-api/pages";

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ title, content }),
      });

      if (!response.ok) throw new Error("Failed to save page");

      // Reset form
      setTitle("");
      setContent("");
      setEditingId(null);

      // Refresh data
      await fetchPages();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEdit = (page: Page) => {
    setTitle(page.title);
    setContent(page.content);
    setEditingId(page.id);
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/docs-api/pages/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) throw new Error("Failed to delete page");
      await fetchPages();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleCancel = () => {
    setTitle("");
    setContent("");
    setEditingId(null);
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Documentation Pages</h1>

      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ marginBottom: "15px" }}>
          <input
            type="text"
            placeholder="Title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ddd" }}
            required
          />
        </div>

        <div style={{ marginBottom: "15px" }}>
          <textarea
            placeholder="Content"
            value={content}
            onChange={(e) => setContent(e.target.value)}
            style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ddd", minHeight: "150px" }}
            required
          />
        </div>

        <div style={{ display: "flex", gap: "10px" }}>
          <button 
            type="submit" 
            style={{ padding: "10px 20px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
          >
            {editingId ? "Update Page" : "Create Page"}
          </button>

          {editingId && (
            <button 
              type="button" 
              onClick={handleCancel}
              style={{ padding: "10px 20px", backgroundColor: "#6c757d", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
            >
              Cancel
            </button>
          )}
        </div>
      </form>

      <h2 style={{ textAlign: "center" }}>All Pages</h2>

      {pages.length === 0 ? (
        <p style={{ textAlign: "center", color: "#666" }}>No pages found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {pages.map((page) => (
            <div 
              key={page.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                flexDirection: "column", 
                gap: "10px"
              }}
            >
              <h3 style={{ margin: "0", color: "#333" }}>{page.title}</h3>
              <p style={{ margin: "0", color: "#555", whiteSpace: "pre-wrap" }}>{page.content}</p>
