export function SupervisorDeleteGuard() {
  const [parts, setParts] = useState<Part[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [supervisorId, setSupervisorId] = useState<number | null>(null);

  useEffect(() => {
    const fetchParts = async () => {
      try {
        const response = await fetch('/api/parts-api/');
        if (!response.ok) {
          throw new Error('Failed to fetch parts');
        }
        const data = await response.json();
        setParts(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    };

    const fetchSupervisorId = async () => {
      try {
        const response = await fetch('/api/parts-api/');
        if (!response.ok) {
          throw new Error('Failed to fetch supervisor info');
        }
        const data = await response.json();
        // Assuming first part's supervisorId is the current supervisor
        setSupervisorId(data[0]?.supervisorId || null);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      }
    };

    fetchParts();
    fetchSupervisorId();
  }, []);

  const handleDelete = async (id: number, supervisorId: number) => {
    // In a real app, we'd check if the current user is a supervisor
    // For now, we'll just simulate the guard behavior
    if (supervisorId === 1) { // Assume 1 is the supervisor ID
      try {
        const response = await fetch(`/api/parts-api/${id}`, {
          method: 'DELETE',
        });
        if (!response.ok) {
          throw new Error('Failed to delete part');
        }
        // Refresh the list after deletion
        const updatedResponse = await fetch('/api/parts-api/');
        const updatedData = await updatedResponse.json();
        setParts(updatedData);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
      }
    } else {
      alert('You are not authorized to delete this record.');
    }
  };

  if (loading) return <div style={{ textAlign: 'center' }}>Loading...</div>;

  if (error) return <div style={{ textAlign: 'center', color: 'red' }}>{error}</div>;

  if (parts.length === 0) return <div style={{ textAlign: 'center' }}>No parts found.</div>;

  return (
    <div style={{
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
      fontFamily: 'system-ui, sans-serif',
