interface Batch {
  id: string;
  cheeseType: string;
  startDate: string;
  agingPeriod: number;
  currentStatus: string;
}

export function BatchList() {
  const [batches, setBatches] = useState<Batch[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [userRole, setUserRole] = useState<string>("user"); // Default role

  useEffect(() => {
    const fetchBatches = async () => {
      try {
        const response = await fetch("/api/aging-batches-api/");
        if (!response.ok) {
          throw new Error(`Failed to fetch batches: ${response.status}`);
        }
        const data = await response.json();
        setBatches(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    const fetchUserRole = async () => {
      try {
        const response = await fetch("/api/user-role"); // Assuming this endpoint exists
        if (!response.ok) {
          throw new Error(`Failed to fetch user role: ${response.status}`);
        }
        const data = await response.json();
        setUserRole(data.role);
      } catch (err) {
        console.error("Error fetching user role:", err);
      }
    };

    fetchBatches();
    fetchUserRole();
  }, []);

  const handleDelete = async (id: string) => {
    if (userRole !== "supervisor") return;

    try {
      const response = await fetch(`/api/aging-batches-api/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete batch: ${response.status}`);
      }
      // Refresh the list after deletion
      const updatedResponse = await fetch("/api/aging-batches-api/");
      if (!updatedResponse.ok) {
        throw new Error(`Failed to refresh batches: ${updatedResponse.status}`);
      }
      const updatedData = await updatedResponse.json();
      setBatches(updatedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (batches.length === 0) {
    return <div style={{ textAlign: "center", padding: "20px" }}>No batches found.</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "system-ui, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Aging Batches</h1>
      <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
        {batches.map((batch) => (
          <div 
            key={batch.id} 
            style={{ 
              border: "1px solid #ccc", 
              borderRadius: "8px", 
              padding: "15px", 
              display: "flex", 
              justifyContent: "space-between", 
              alignItems: "center"
            }}
          >
            <div>
              <strong>{batch.cheeseType}</strong> - Started: {new Date(batch.startDate).toLocaleDateString()} - Aging Period: {batch.agingPeriod} days - Status: {batch.currentStatus}
            </div>
            {userRole === "supervisor" && (
              <button 
                onClick={() => handleDelete(batch.id)}
                style={{ 
                  backgroundColor: "#ff4d4d", 
                  color: "white", 
                  border: "none", 
                  borderRadius: "4px", 
                  padding: "5px 10px", 
                  cursor: "pointer"
                }}
              >
                Delete
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";

export function OwnerOnlyHistoryExport() {
  const [bookings, setBookings] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    try {
      const response = await fetch('/api/bookings-api/');
      if (!response.ok) {
        throw new Error(`Failed to fetch bookings: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  };

  const handleExport = async () => {
    try {
      const response = await fetch('/api/export-service/export/csv', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(`Failed to export CSV: ${response.status} ${response.statusText}`);
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'booking_history.csv';
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Owner-Only History Export</h1>
      <p style={{ textAlign: 'center' }}>Download a CSV of every booking ever made.</p>

      <div style={{ marginBottom: '20px', textAlign: 'center' }}>
        <button 
          onClick={handleExport}
          style={{
            backgroundColor: '#007bff',
            color: 'white',
            border: 'none',
            padding: '10px 20px',
            borderRadius: '5px',
            cursor: 'pointer',
            fontSize: '16px'
          }}
        >
          Export All Bookings to CSV
        </button>
      </div>

      <div style={{ marginBottom: '20px' }}>
        <h2>Booking History</h2>
        {bookings.length === 0 ? (
          <p>No bookings found.</p>
        ) : (
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: '1px solid #ccc' }}>
                <th style={{ padding: '8px', textAlign: 'left' }}>ID</th>
                <th style={{ padding: '8px', textAlign: 'left' }}>User ID</th>
                <th style={{ padding: '8px', textAlign: 'left' }}>Desk ID</th>
                <th style={{ padding: '8px', textAlign: 'left' }}>Start Date</th>
                <th style={{ padding: '8px', textAlign: 'left' }}>End Date</th>
              </tr>
            </thead>
            <tbody>
              {bookings.map(booking => (
                <tr key={booking.id} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '8px' }}>{booking.id}</td>
                  <td style={{ padding: '8px' }}>{booking.userId}</td>
                  <td style={{ padding: '8px' }}>{booking.deskId}</td>
                  <td style={{ padding: '8px' }}>{new Date(booking.startDate).toLocaleDateString()}</td>
                  <td style={{ padding: '8px' }}>{new Date(booking.endDate).toLocaleDateString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

