import { useEffect, useState } from "react";

export function OwnerOnlyExportPanel() {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleExport = async () => {
    setIsLoading(true);
    setError(null);

    try {
      const response = await fetch("/api/export-service/export/csv", {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
        },
      });

      if (!response.ok) {
        throw new Error(`Failed to export: ${response.status} ${response.statusText}`);
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "grant-applications.csv";
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div style={{
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px",
    }}>
      <h1>Owner-Only Export Panel</h1>
      <p>Download the raw application dataset as CSV.</p>

      <button 
        onClick={handleExport}
        disabled={isLoading}
        style={{
          backgroundColor: "#007bff",
          color: "white",
          border: "none",
          borderRadius: "4px",
          padding: "10px 20px",
          fontSize: "16px",
          cursor: isLoading ? "not-allowed" : "pointer",
        }}
      >
        {isLoading ? "Exporting..." : "Export as CSV"}
      </button>

      {error && (
        <div style={{
          marginTop: "20px",
          padding: "10px",
          backgroundColor: "#f8d7da",
          borderColor: "#f5c6cb",
          color: "#721c24",
          borderRadius: "4px",
          border: "1px solid",
        }}>
          Error: {error}
        </div>
      )}
    </div>
  );
}

