}

export function RoomBookingView() {
  const [rooms, setRooms] = useState<Room[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedRoomId, setSelectedRoomId] = useState<string>("");
  const [startTime, setStartTime] = useState<string>("");
  const [endTime, setEndTime] = useState<string>("");

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [roomsResponse, bookingsResponse] = await Promise.all([
          fetch("/api/bookings-api/"),
          fetch("/api/bookings-api/"),
        ]);

        if (!roomsResponse.ok || !bookingsResponse.ok) {
          throw new Error("Failed to fetch data");
        }

        const roomsData = await roomsResponse.json();
        const bookingsData = await bookingsResponse.json();

        setRooms(roomsData);
        setBookings(bookingsData);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleBookSlot = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!selectedRoomId || !startTime || !endTime) {
      setError("Please fill in all fields");
      return;
    }

    try {
      const response = await fetch("/api/bookings-api/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          roomId: selectedRoomId,
          startTime,
          endTime,
          bookedBy: "Current User", // In a real app, this would come from auth
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to book slot");
      }

      // Refresh data after successful booking
      const [roomsResponse, bookingsResponse] = await Promise.all([
        fetch("/api/bookings-api/"),
        fetch("/api/bookings-api/"),
      ]);

      if (!roomsResponse.ok || !bookingsResponse.ok) {
        throw new Error("Failed to refresh data");
      }

      const roomsData = await roomsResponse.json();
      const bookingsData = await bookingsResponse.json();

      setRooms(roomsData);
      setBookings(bookingsData);

      // Reset form
      setSelectedRoomId("");
      setStartTime("");
      setEndTime("");
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return (
      <div style={{ textAlign: "center", padding: "20px", color: "red" }}>
        Error: {error}
      </div>
    );
  }

  return (
    <div
      style={{
        maxWidth: "800px",
        margin: "0 auto",
        padding: "20px",
        fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
      }}
    >
      <h1 style={{ textAlign: "center" }}>Meeting Room Booking</h1>

      <div style={{ marginBottom: "30px" }}>
        <h2>Available Rooms</h2>
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            gap: "15px",
          }}
        >
          {rooms.length === 0 ? (
            <p>No rooms available.</p>
          ) : (
            rooms.map((room) => (
              <div
                key={room.id}
                style={{
                  border: "1px solid #ccc",
                  borderRadius: "8px",
                  padding: "15px",
                  minWidth: "200px",
                  flex: "1 1 calc(50% - 15px)",
                }}
              >
                <h3>{room.name}</h3>
                <p>Capacity: {room.capacity} people</p>
              </div>
            ))
          )}
        </div>
      </div>

      <div style={{ marginBottom: "30px" }}>
        <h2>Book a Time Slot</h2>
        <form onSubmit={handleBookSlot}>
          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="roomId">Room:</label>
            <select
              id="roomId"
              value={selectedRoomId}
              onChange={(e) => setSelectedRoomId(e.target.value)}
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            >
              <option value="">Select a room</option>
              {rooms.map((room) => (
                <option key={room.id} value={room.id}>
                  {room.name}
                </option>
              ))}
            </select>
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="startTime">Start Time:</label>
            <input
              type="datetime-local"
              id="startTime"
              value={startTime}
              onChange={(e) => setStartTime(e.target.value)}
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            />
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="endTime">End Time:</label>
            <input
              type="datetime-local"
              id="endTime"
              value={endTime}
              onChange={(e) => setEndTime(e.target.value)}
              style={{ width: "100%", padding: "8px", marginTop: "5px" }}
            />
          </div>

          <button
            type="submit"
            style={{
              backgroundColor: "#007bff",
              color: "white",
              border: "none",
              padding: "10px 20px",
              borderRadius: "4px",
              cursor: "pointer",
            }}
          >
            Book Slot
          </button>
        </form>
      </div>

      <div>
        <h2>Upcoming Bookings</h2>
        {bookings.length === 0 ? (
          <p>No upcoming bookings.</p>
        ) : (
          <table
            style={{
              width: "100%",
              borderCollapse: "collapse",
              marginBottom: "20px",
            }}
          >
            <thead>
              <tr>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>Room</th>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>Start Time</th>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>End Time</th>
                <th style={{ border: "1px solid #ddd", padding: "8px" }}>Booked By</th>
              </tr>
            </thead>
            <tbody>
              {bookings.map((booking) => (
                <tr key={booking.id}>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {booking.roomName}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {new Date(booking.startTime).toLocaleString()}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {new Date(booking.endTime).toLocaleString()}
                  </td>
                  <td style={{ border: "1px solid #ddd", padding: "8px" }}>
                    {booking.bookedBy}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

