import { useEffect, useState } from "react";

interface Class {
  id: number;
  name: string;
  description: string;
  date: string;
  time: string;
  maxBookings: number;
}

interface Booking {
  id: number;
  classId: number;
  className: string;
  userEmail: string;
  bookingDate: string;
}

export function AdminPanel() {
  const [classes, setClasses] = useState<Class[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchClasses();
    fetchBookings();
  }, []);

  const fetchClasses = async () => {
    try {
      const response = await fetch('/api/classes');
      if (!response.ok) throw new Error('Failed to fetch classes');
      const data = await response.json();
      setClasses(data);
    } catch (err) {
      setError('Error loading classes');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchBookings = async () => {
    try {
      const response = await fetch('/api/bookings');
      if (!response.ok) throw new Error('Failed to fetch bookings');
      const data = await response.json();
      setBookings(data);
    } catch (err) {
      setError('Error loading bookings');
      console.error(err);
    }
  };

  const handleCancelBooking = async (bookingId: number) => {
    try {
      const response = await fetch(`/api/bookings/${bookingId}`, {
        method: 'DELETE',
      });
      if (!response.ok) throw new Error('Failed to cancel booking');
      fetchBookings(); // Refresh bookings list
    } catch (err) {
      setError('Error cancelling booking');
      console.error(err);
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{
      fontFamily: 'system-ui, sans-serif',
      maxWidth: '800px',
      margin: '0 auto',
      padding: '20px',
    }}>
      <h1 style={{ textAlign: 'center' }}>Admin Panel</h1>

      <section style={{ marginBottom: '30px' }}>
        <h2>Manage Classes</h2>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '10px' }}>
          {classes.length > 0 ? (
            classes.map(cls => (
              <div key={cls.id} style={{
                border: '1px solid #ccc',
                borderRadius: '8px',
                padding: '15px',
                width: '100%',
                maxWidth: '300px',
              }}>
                <h3>{cls.name}</h3>
                <p>{cls.description}</p>
                <p><strong>Date:</strong> {cls.date}</p>
                <p><strong>Time:</strong> {cls.time}</p>
                <p><strong>Max Bookings:</strong> {cls.maxBookings}</p>
              </div>
            ))
          ) : (
            <p>No classes found.</p>
          )}
        </div>
      </section>

      <section style={{ marginBottom: '30px' }}>
        <h2>View Bookings</h2>
        {bookings.length > 0 ? (
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: '1px solid #ccc' }}>
                <th style={{ textAlign: 'left', padding: '10px' }}>Class</th>
                <th style={{ textAlign: 'left', padding: '10px' }}>User Email</th>
                <th style={{ textAlign: 'left', padding: '10px' }}>Booking Date</th>
                <th style={{ textAlign: 'left', padding: '10px' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {bookings.map(booking => (
                <tr key={booking.id} style={{ borderBottom: '1px solid #eee' }}>
                  <td style={{ padding: '10px' }}>{booking.className}</td>
                  <td style={{ padding: '10px' }}>{booking.userEmail}</td>
                  <td style={{ padding: '10px' }}>{booking.bookingDate}</td>
                  <td style={{ padding: '10px' }}>
                    <button 
                      onClick={() => handleCancelBooking(booking.id)}
                      style={{
                        backgroundColor: '#ff4d4d',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        padding: '5px 10px',
                        cursor: 'pointer',
                      }}
                    >
                      Cancel
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <p>No bookings found.</p>
        )}
      </section>
    </div>
  );
}

