          theater: "Theater 1",
          totalSeats: 100,
          availableSeats: 45,
        };

        const mockSeats: Seat[] = [];
        for (let i = 1; i <= 100; i++) {
          mockSeats.push({
            id: `seat-${i}`,
            row: String.fromCharCode(65 + Math.floor((i - 1) / 10)),
            number: ((i - 1) % 10) + 1,
            isAvailable: i > 55, // Mock some unavailable seats
          });
        }

