        <p><strong>Theater:</strong> {showtime.theater}</p>
        <p><strong>Available Seats:</strong> {showtime.availableSeats}/{showtime.totalSeats}</p>
      </div>

      <h3>Select Your Seats</h3>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "10px", marginBottom: "20px" }}>
        {seats.map(seat => (
          <button
            key={seat.id}
            onClick={() => handleSeatSelect(seat.id)}
            style={{
              backgroundColor: selectedSeats.includes(seat.id) ? "#4CAF50" : seat.isAvailable ? "#e0e0e0" : "#ccc",
              border: "none",
              borderRadius: "4px",
              padding: "8px 12px",
              cursor: seat.isAvailable ? "pointer" : "default",
              opacity: seat.isAvailable ? 1 : 0.5,
              fontSize: "14px",
            }}
            disabled={!seat.isAvailable}
          >
            {seat.row}{seat.number}
          </button>
        ))}
      </div>

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div>
          <p><strong>Selected Seats:</strong> {selectedSeats.length}</p>
          <p>{selectedSeats.length > 0 && `Seats: ${selectedSeats.map(id => {
            const seat = seats.find(s => s.id === id);
            return seat ? `${seat.row}${seat.number}` : "";
          }).join(", ")}`}</p>
        </div>
        <button 
          onClick={handleBooking}
          style={{
            backgroundColor: "#2196F3",
            color: "white",
            border: "none",
            borderRadius: "4px",
            padding: "10px 20px",
            fontSize: "16px",
            cursor: "pointer",
          }}
          disabled={selectedSeats.length === 0}
        >
          Complete Booking
        </button>
      </div>
    </div>
  );
}

