import { useEffect, useState } from "react";

interface Cake {
  id: number;
  name: string;
  basePrice: number;
  customizationOptions: {
    flavor: string;
    frosting: string;
    decorations: string[];
  };
}

interface CartItem {
  cake: Cake;
  quantity: number;
}

export function ShoppingCart() {
  const [cartItems, setCartItems] = useState<CartItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // Simulate fetching cart items from API
    const fetchCartItems = async () => {
      try {
        // In a real app, this would be an actual API call
        // const response = await fetch('/api/cart');
        // const items = await response.json();

        // Mock data for demonstration
        const mockItems: CartItem[] = [
          {
            cake: {
              id: 1,
              name: "Chocolate Fudge Cake",
              basePrice: 25,
              customizationOptions: {
                flavor: "Rich Chocolate",
                frosting: "Ganache",
                decorations: ["Candied Violets", "Gold Leaf"]
              }
            },
            quantity: 2
          },
          {
            cake: {
              id: 2,
              name: "Vanilla Dream Cake",
              basePrice: 20,
              customizationOptions: {
                flavor: "Classic Vanilla",
                frosting: "Buttercream",
                decorations: ["Fresh Berries"]
              }
            },
            quantity: 1
          }
        ];

        setCartItems(mockItems);
        setLoading(false);
      } catch (err) {
        setError("Failed to load cart items");
        setLoading(false);
      }
    };

    fetchCartItems();
  }, []);

  const calculateTotal = () => {
    return cartItems.reduce((total, item) => {
      const customizationPrice = item.cake.customizationOptions.decorations.length * 5;
      return total + (item.cake.basePrice + customizationPrice) * item.quantity;
    }, 0);
  };

  const handleQuantityChange = (id: number, newQuantity: number) => {
    if (newQuantity < 1) return;

    setCartItems(prevItems => 
      prevItems.map(item => 
        item.cake.id === id ? { ...item, quantity: newQuantity } : item
      )
    );
  };

  const removeItem = (id: number) => {
    setCartItems(prevItems => prevItems.filter(item => item.cake.id !== id));
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  if (cartItems.length === 0) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Your cart is empty</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Your Shopping Cart</h1>

      <div style={{ marginBottom: "20px" }}>
        {cartItems.map(item => (
          <div key={item.cake.id} style={{ border: "1px solid #ddd", borderRadius: "8px", padding: "15px", marginBottom: "15px" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <h3>{item.cake.name}</h3>
                <p>Flavor: {item.cake.customizationOptions.flavor}</p>
                <p>Frosting: {item.cake.customizationOptions.frosting}</p>
                <p>Decorations: {item.cake.customizationOptions.decorations.join(", ")}</p>
              </div>
              <div style={{ textAlign: "right" }}>
                <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
                  <button 
                    onClick={() => handleQuantityChange(item.cake.id, item.quantity - 1)}
                    disabled={item.quantity <= 1}
                    style={{ padding: "5px 10px", backgroundColor: "#f0f0f0", border: "none", borderRadius: "4px" }}
                  >
                    -
                  </button>
                  <span style={{ minWidth: "30px", textAlign: "center" }}>{item.quantity}</span>
                  <button 
                    onClick={() => handleQuantityChange(item.cake.id, item.quantity + 1)}
                    style={{ padding: "5px 10px", backgroundColor: "#f0f0f0", border: "none", borderRadius: "4px" }}
                  >
                    +
                  </button>
                </div>
                <p style={{ marginTop: "10px", fontWeight: "bold" }}>
                  ${(item.cake.basePrice + item.cake.customizationOptions.decorations.length * 5) * item.quantity}
                </p>
              </div>
            </div>
            <button 
              onClick={() => removeItem(item.cake.id)}
              style={{ 
                marginTop: "10px", 
                padding: "5px 10px", 
                backgroundColor: "#ff4d4d", 
                color: "white", 
                border: "none", 
                borderRadius: "4px" 
              }}
            >
              Remove
            </button>
          </div>
        ))}
      </div>

      <div style={{ 
        border: "1px solid #ddd", 
        borderRadius: "8px", 
        padding: "15px", 
        backgroundColor: "#f9f9f9" 
      }}>
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "10px" }}>
          <span>Total:</span>
          <span style={{ fontWeight: "bold" }}>${calculateTotal()}</span>
        </div>
        <button 
          style={{ 
            width: "100%", 
            padding: "12px", 
            backgroundColor: "#4CAF50", 
            color: "white", 
            border: "none", 
            borderRadius: "4px", 
            fontSize: "16px", 
            fontWeight: "bold" 
          }}
        >
          Proceed to Checkout
        </button>
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";

interface RouteLog {
  id: number;
  driverName: string;
  startDate: string;
  endDate: string;
  status: string;
}

export function RouteLogList() {
  const [routeLogs, setRouteLogs] = useState<RouteLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [driverName, setDriverName] = useState("");

  useEffect(() => {
    fetchRouteLogs();
  }, []);

  const fetchRouteLogs = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/route-logs?startDate=${startDate}&endDate=${endDate}&driverName=${driverName}`);
      if (!response.ok) {
        throw new Error(`Failed to fetch route logs: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      setRouteLogs(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    fetchRouteLogs();
  };

  const formatDate = (dateString: string) => {
    const options: Intl.DateTimeFormatOptions = { year: "numeric", month: "short", day: "numeric" };
    return new Date(dateString).toLocaleDateString(undefined, options);
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Route Logs</h1>

      <form onSubmit={handleSearch} style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <div style={{ display: "flex", flexDirection: "row", gap: "10px", flexWrap: "wrap" }}>
          <input
            type="date"
            value={startDate}
            onChange={(e) => setStartDate(e.target.value)}
            style={{ flex: 1, minWidth: "150px" }}
          />
          <input
            type="date"
            value={endDate}
            onChange={(e) => setEndDate(e.target.value)}
            style={{ flex: 1, minWidth: "150px" }}
          />
          <input
            type="text"
            placeholder="Driver Name"
            value={driverName}
            onChange={(e) => setDriverName(e.target.value)}
            style={{ flex: 1, minWidth: "150px" }}
          />
          <button type="submit" style={{ flex: 1, minWidth: "100px", padding: "8px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}>
            Search
          </button>
        </div>
      </form>

      {routeLogs.length === 0 ? (
        <div style={{ textAlign: "center", padding: "20px" }}>No route logs found.</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {routeLogs.map((log) => (
            <div key={log.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px", backgroundColor: "#f9f9f9" }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <h3 style={{ margin: "0 0 5px 0" }}>{log.driverName}</h3>
                  <p style={{ margin: "0 0 5px 0" }}>
                    {formatDate(log.startDate)} - {formatDate(log.endDate)}
                  </p>
                  <p style={{ margin: "0", color: "#666" }}>{log.status}</p>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

