import { useEffect, useState } from "react";

interface Student {
  id: number;
  name: string;
  email: string;
  phone: string;
  department: string;
}

export function StudentManagement() {
  const [students, setStudents] = useState<Student[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState<Omit<Student, "id">>({ 
    name: "", 
    email: "", 
    phone: "", 
    department: ""
  });
  const [editingId, setEditingId] = useState<number | null>(null);
  const [isAdding, setIsAdding] = useState(false);

  useEffect(() => {
    fetchStudents();
  }, []);

  const fetchStudents = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/students");
      if (!response.ok) throw new Error("Failed to fetch students");
      const data = await response.json();
      setStudents(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const url = editingId 
        ? `/api/students/${editingId}`
        : "/api/students";
      const method = editingId ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

      if (!response.ok) throw new Error("Failed to save student");

      fetchStudents();
      resetForm();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const resetForm = () => {
    setFormData({ name: "", email: "", phone: "", department: "" });
    setEditingId(null);
    setIsAdding(false);
  };

  const handleEdit = (student: Student) => {
    setFormData({ 
      name: student.name, 
      email: student.email, 
      phone: student.phone, 
      department: student.department 
    });
    setEditingId(student.id);
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/students/${id}`, { method: "DELETE" });
      if (!response.ok) throw new Error("Failed to delete student");
      fetchStudents();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleAddNew = () => {
    setIsAdding(true);
    resetForm();
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  return (
    <div style={{ 
      maxWidth: "800px", 
      margin: "0 auto", 
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
    }}>
      <h1 style={{ textAlign: "center" }}>Student Management</h1>

      {error && <div style={{ color: "red", marginBottom: "20px" }}>{error}</div>}

      <div style={{ marginBottom: "20px", display: "flex", justifyContent: "center" }}>
        <button 
          onClick={handleAddNew}
          style={{ 
            backgroundColor: "#007bff", 
            color: "white", 
            border: "none", 
            padding: "10px 20px", 
            borderRadius: "4px", 
            cursor: "pointer" 
          }}
        >
          Add New Student
        </button>
      </div>

      {isAdding || editingId !== null ? (
        <form onSubmit={handleSubmit} style={{ 
          backgroundColor: "#f8f9fa", 
          padding: "20px", 
          borderRadius: "8px", 
          marginBottom: "20px" 
        }}>
          <div style={{ marginBottom: "15px" }}>
            <input
              type="text"
              name="name"
              placeholder="Name"
              value={formData.name}
              onChange={handleInputChange}
              style={{ 
                width: "100%", 
                padding: "8px", 
                borderRadius: "4px", 
                border: "1px solid #ccc" 
              }}
              required
            />
          </div>

          <div style={{ marginBottom: "15px" }}>
            <input
              type="email"
              name="email"
              placeholder="Email"
              value={formData.email}
              onChange={handleInputChange}
              style={{ 
                width: "100%", 
                padding: "8px", 
                borderRadius: "4px", 
                border: "1px solid #ccc" 
              }}
              required
            />
          </div>

          <div style={{ marginBottom: "15px" }}>
            <input
              type="tel"
              name="phone"
              placeholder="Phone"
              value={formData.phone}
              onChange={handleInputChange}
              style={{ 
                width: "100%", 
                padding: "8px", 
                borderRadius: "4px", 
                border: "1px solid #ccc" 
              }}
              required
            />
          </div>

          <div style={{ marginBottom: "15px" }}>
            <select
              name="department"
              value={formData.department}
              onChange={handleInputChange}
              style={{ 
                width: "100%", 
                padding: "8px", 
                borderRadius: "4px", 
                border: "1px solid #ccc" 
              }}
              required
            >
              <option value="">Select Department</option>
              <option value="Computer Science">Computer Science</option>
              <option value="Electrical Engineering">Electrical Engineering</option>
              <option value="Mechanical Engineering">Mechanical Engineering</option>
              <option value="Civil Engineering">Civil Engineering</option>
            </select>
          </div>

          <div style={{ display: "flex", gap: "10px" }}>
            <button 
              type="submit"
              style={{ 
                backgroundColor: "#28a745", 
                color: "white", 
                border: "none", 
                padding: "10px 20px", 
                borderRadius: "4px", 
                cursor: "pointer" 
              }}
            >
              {editingId ? "Update Student" : "Add Student"}
            </button>
            <button 
              type="button"
              onClick={resetForm}
              style={{ 
                backgroundColor: "#6c757d", 
                color: "white", 
                border: "none", 
                padding: "10px 20px", 
                borderRadius: "4px", 
                cursor: "pointer" 
              }}
            >
              Cancel
            </button>
          </div>
        </form>
      ) : null}

      <h2>Student Records</h2>

      {students.length === 0 ? (
        <p style={{ textAlign: "center", color: "#6c757d" }}>No students found.</p>
      ) : (
        <div style={{ 
          display: "flex", 
          flexDirection: "column", 
          gap: "10px" 
        }}>
          {students.map(student => (
            <div 
              key={student.id} 
              style={{ 
                border: "1px solid #dee2e6", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center" 
              }}
            >
              <div>
                <strong>{student.name}</strong><br />
                <small>{student.email} | {student.phone}</small><br />
                <small>Department: {student.department}</small>
              </div>
              <div style={{ display: "flex", gap: "5px" }}>
                <button 
                  onClick={() => handleEdit(student)}
                  style={{ 
                    backgroundColor: "#17a2b8", 
                    color: "white", 
                    border: "none", 
                    padding: "5px 10px", 
                    borderRadius: "4px", 
                    cursor: "pointer" 
                  }}
                >
                  Edit
                </button>
                <button 
                  onClick={() => handleDelete(student.id)}
                  style={{ 
                    backgroundColor: "#dc3545", 
                    color: "white", 
                    border: "none", 
                    padding: "5px 10px", 
                    borderRadius: "4px", 
                    cursor: "pointer" 
                  }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

interface Company {
