export function ScheduleList() {
  const [collections, setCollections] = useState<WasteCollection[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filters, setFilters] = useState({
    date: "",
    type: "",
    status: "",
  });

  useEffect(() => {
    const fetchCollections = async () => {
      try {
        setLoading(true);
        // In a real app, this would be an API call
        // const response = await fetch('/api/collections');
        // const data = await response.json();

        // Mock data for demonstration
        const mockData: WasteCollection[] = [
          { id: "1", date: "2023-06-15", type: "Organic", status: "scheduled" },
          { id: "2", date: "2023-06-16", type: "Plastic", status: "completed" },
          { id: "3", date: "2023-06-17", type: "Paper", status: "scheduled" },
          { id: "4", date: "2023-06-18", type: "Glass", status: "cancelled" },
        ];

        setCollections(mockData);
        setError(null);
      } catch (err) {
        setError("Failed to load collections");
      } finally {
        setLoading(false);
      }
    };

    fetchCollections();
  }, []);

  const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFilters(prev => ({ ...prev, [name]: value }));
  };

  const filteredCollections = collections.filter(collection => {
    return (
      (filters.date === "" || collection.date.includes(filters.date)) &&
      (filters.type === "" || collection.type.toLowerCase().includes(filters.type.toLowerCase())) &&
      (filters.status === "" || collection.status === filters.status)
    );
  });

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Waste Collection Schedule</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="date"
          name="date"
          placeholder="Filter by date"
          value={filters.date}
          onChange={handleFilterChange}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          name="type"
          value={filters.type}
          onChange={handleFilterChange}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="">All Types</option>
          <option value="Organic">Organic</option>
          <option value="Plastic">Plastic</option>
          <option value="Paper">Paper</option>
          <option value="Glass">Glass</option>
        </select>

        <select
          name="status"
          value={filters.status}
          onChange={handleFilterChange}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="">All Statuses</option>
          <option value="scheduled">Scheduled</option>
          <option value="completed">Completed</option>
          <option value="cancelled">Cancelled</option>
        </select>
      </div>

      {filteredCollections.length === 0 ? (
        <div style={{ textAlign: "center", padding: "20px" }}>No collections found.</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {filteredCollections.map(collection => (
            <div 
              key={collection.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                backgroundColor: "#f9f9f9",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                flexWrap: "wrap"
              }}
            >
              <div>
                <strong>{collection.date}</strong> - {collection.type}
                <br />
                <span style={{ 
                  fontSize: "0.9em", 
                  color: collection.status === "completed" ? "green" : 
                         collection.status === "cancelled" ? "red" : "orange" 
                }}>
                  {collection.status.charAt(0).toUpperCase() + collection.status.slice(1)}
                </span>
              </div>
              <div>
                <button 
                  style={{ 
                    backgroundColor: "#007bff", 
                    color: "white", 
                    border: "none", 
                    borderRadius: "4px", 
                    padding: "5px 10px", 
                    cursor: "pointer" 
                  }}
