            border: '1px solid #ccc', 
            borderRadius: '8px', 
            padding: '15px', 
            backgroundColor: '#f9f9f9'
          }}>
            <h3>{selectedFeedback.guestName}</h3>
            <p><strong>Rating:</strong> {selectedFeedback.rating}/5</p>
            <p><strong>Category:</strong> {selectedFeedback.category}</p>
            <p><strong>Date:</strong> {selectedFeedback.date}</p>
            <p><strong>Comment:</strong></p>
            <p>{selectedFeedback.comment}</p>
          </div>
        </div>
      ) : (
        <>
