import { useEffect, useState } from "react";

interface Customer {
  id: number;
  name: string;
  serviceType: string;
  appointmentTime: string;
}

export function CustomerFormPage() {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [formData, setFormData] = useState({
    name: "",
    serviceType: "",
    appointmentTime: ""
  });
  const [editingId, setEditingId] = useState<number | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchCustomers();
  }, []);

  const fetchCustomers = async () => {
    try {
      const response = await fetch("/api/customers");
      if (!response.ok) throw new Error("Failed to fetch customers");
      const data = await response.json();
      setCustomers(data);
      setLoading(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
      setLoading(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const url = editingId 
        ? `/api/customers/${editingId}`
        : "/api/customers";

      const method = editingId ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData)
      });

      if (!response.ok) throw new Error("Failed to save customer");

      fetchCustomers();
      resetForm();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const handleEdit = (customer: Customer) => {
    setFormData({
      name: customer.name,
      serviceType: customer.serviceType,
      appointmentTime: customer.appointmentTime
    });
    setEditingId(customer.id);
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/customers/${id}`, { method: "DELETE" });
      if (!response.ok) throw new Error("Failed to delete customer");
      fetchCustomers();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const resetForm = () => {
    setFormData({ name: "", serviceType: "", appointmentTime: "" });
    setEditingId(null);
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  const formStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
    marginBottom: "20px",
    maxWidth: "500px",
    margin: "0 auto",
    padding: "20px",
    border: "1px solid #ccc",
    borderRadius: "8px",
    fontFamily: "system-ui, sans-serif"
  };

  const inputStyle: React.CSSProperties = {
    padding: "8px",
    borderRadius: "4px",
    border: "1px solid #ccc",
    fontSize: "16px"
  };

  const buttonStyle: React.CSSProperties = {
    padding: "10px",
    backgroundColor: "#007bff",
    color: "white",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "16px"
  };

  const listStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    gap: "10px",
    maxWidth: "500px",
    margin: "0 auto",
    fontFamily: "system-ui, sans-serif"
  };

  const itemStyle: React.CSSProperties = {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "10px",
    border: "1px solid #ccc",
    borderRadius: "4px"
  };

  const buttonGroupStyle: React.CSSProperties = {
    display: "flex",
    gap: "5px"
  };

  return (
    <div style={{ padding: "20px", maxWidth: "600px", margin: "0 auto" }}>
      <h1 style={{ textAlign: "center", fontFamily: "system-ui, sans-serif" }}>Customer Queue</h1>

      <form onSubmit={handleSubmit} style={formStyle}>
        <input
          type="text"
          name="name"
          placeholder="Customer Name"
          value={formData.name}
          onChange={handleChange}
          style={inputStyle}
        />

        <select
          name="serviceType"
          value={formData.serviceType}
          onChange={handleChange}
          style={inputStyle}
        >
          <option value="">Select Service Type</option>
          <option value="Haircut">Haircut</option>
          <option value="Beard Trim">Beard Trim</option>
          <option value="Hair Coloring">Hair Coloring</option>
          <option value="Shave">Shave</option>
        </select>

        <input
          type="datetime-local"
          name="appointmentTime"
          value={formData.appointmentTime}
          onChange={handleChange}
          style={inputStyle}
        />

        <button type="submit" style={buttonStyle}>
          {editingId ? "Update Customer" : "Add Customer"}
        </button>

        {editingId && (
          <button type="button" onClick={resetForm} style={{ ...buttonStyle, backgroundColor: "#6c757d" }}>
            Cancel Edit
          </button>
        )}
      </form>

      <div style={listStyle}>
        <h2 style={{ fontFamily: "system-ui, sans-serif" }}>Queue List</h2>

        {customers.length === 0 ? (
          <p style={{ textAlign: "center", fontFamily: "system-ui, sans-serif" }}>No customers in queue.</p>
        ) : (
          customers.map(customer => (
            <div key={customer.id} style={itemStyle}>
              <div>
                <strong>{customer.name}</strong> - {customer.serviceType} - {new Date(customer.appointmentTime).toLocaleString()}
              </div>
              <div style={buttonGroupStyle}>
                <button 
                  onClick={() => handleEdit(customer)} 
                  style={{ ...buttonStyle, backgroundColor: "#17a2b8" }}
                >
                  Edit
                </button>
                <button 
                  onClick={() => handleDelete(customer.id)} 
                  style={{ ...buttonStyle, backgroundColor: "#dc3545" }}
                >
                  Delete
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";

interface Note {
  id: number;
  title: string;
  content: string;
  tags: string[];
}

export function NotesListPage() {
  const [notes, setNotes] = useState<Note[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedTags, setSelectedTags] = useState<string[]>([]);

  useEffect(() => {
    fetchNotes();
  }, []);

  const fetchNotes = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/notes");
      if (!response.ok) {
        throw new Error(`Failed to fetch notes: ${response.status}`);
      }
      const data = await response.json();
      setNotes(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const uniqueTags = Array.from(
    new Set(notes.flatMap(note => note.tags))
  );

  const filteredNotes = notes.filter(note => {
    const matchesSearch = note.title
      .toLowerCase()
      .includes(searchTerm.toLowerCase()) ||
      note.content
        .toLowerCase()
        .includes(searchTerm.toLowerCase());

    const matchesTags = selectedTags.length === 0 ||
      selectedTags.every(tag => note.tags.includes(tag));

    return matchesSearch && matchesTags;
  });

  const toggleTag = (tag: string) => {
    setSelectedTags(prev => 
      prev.includes(tag) 
        ? prev.filter(t => t !== tag) 
        : [...prev, tag]
    );
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
    }}>
      <h1 style={{ textAlign: "center" }}>Notes</h1>

      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search notes..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{
            width: "100%",
            padding: "10px",
            borderRadius: "4px",
            border: "1px solid #ccc",
            fontSize: "16px"
          }}
        />
      </div>

      <div style={{ marginBottom: "20px" }}>
        <strong>Filter by tags:</strong>
        <div style={{ display: "flex", flexWrap: "wrap", gap: "10px", marginTop: "10px" }}>
          {uniqueTags.map(tag => (
            <button
              key={tag}
              onClick={() => toggleTag(tag)}
              style={{
                backgroundColor: selectedTags.includes(tag) ? "#007bff" : "#f8f9fa",
                color: selectedTags.includes(tag) ? "white" : "black",
                border: "1px solid #007bff",
                borderRadius: "4px",
                padding: "5px 10px",
                cursor: "pointer",
                fontSize: "14px"
              }}
            >
              {tag}
            </button>
          ))}
        </div>
      </div>

      {filteredNotes.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>
          {searchTerm || selectedTags.length > 0
            ? "No notes found matching your criteria."
            : "No notes available."}
        </p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {filteredNotes.map(note => (
            <div
              key={note.id}
              style={{
                border: "1px solid #ddd",
                borderRadius: "8px",
                padding: "15px",
                backgroundColor: "#fff"
              }}
            >
              <h3 style={{ margin: "0 0 10px 0", color: "#333" }}>
                {note.title}
              </h3>
              <p style={{ margin: "0 0 10px 0", color: "#666" }}>
                {note.content}
              </p>
              <div style={{ display: "flex", flexWrap: "wrap", gap: "5px" }}>
                {note.tags.map(tag => (
                  <span
                    key={tag}
                    style={{
                      backgroundColor: "#e9ecef",
                      color: "#495057",
                      padding: "2px 8px",
                      borderRadius: "4px",
                      fontSize: "12px"
                    }}
                  >
                    {tag}
                  </span>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

