import { useEffect, useState } from "react";

interface Subscription {
  id: string;
  name: string;
  price: number;
  renewalDate: string;
  status: "active" | "inactive";
}

export function Dashboard() {
  const [subscriptions, setSubscriptions] = useState<Subscription[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchSubscriptions = async () => {
      try {
        const response = await fetch("/api/subscriptions");
        if (!response.ok) {
          throw new Error(`Failed to fetch: ${response.status}`);
        }
        const data = await response.json();
        setSubscriptions(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
      } finally {
        setLoading(false);
      }
    };

    fetchSubscriptions();
  }, []);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  const activeSubscriptions = subscriptions.filter(sub => sub.status === "active");
  const upcomingRenewals = activeSubscriptions
    .filter(sub => new Date(sub.renewalDate) > new Date())
    .sort((a, b) => new Date(a.renewalDate).getTime() - new Date(b.renewalDate).getTime());

  const formatDate = (dateString: string) => {
    const options: Intl.DateTimeFormatOptions = { year: "numeric", month: "short", day: "numeric" };
    return new Date(dateString).toLocaleDateString(undefined, options);
  };

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Subscription Dashboard</h1>

      <div style={{ marginBottom: "30px" }}>
        <h2>Upcoming Renewals</h2>
        {upcomingRenewals.length === 0 ? (
          <p>No upcoming renewals</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {upcomingRenewals.map(sub => (
              <div key={sub.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
                <div style={{ display: "flex", justifyContent: "space-between" }}>
                  <span><strong>{sub.name}</strong></span>
                  <span>${sub.price.toFixed(2)}</span>
                </div>
                <div style={{ marginTop: "5px", fontSize: "0.9em", color: "#666" }}>
                  Renewal Date: {formatDate(sub.renewalDate)}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div style={{ marginBottom: "30px" }}>
        <h2>Active Subscriptions</h2>
        {activeSubscriptions.length === 0 ? (
          <p>No active subscriptions</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {activeSubscriptions.map(sub => (
              <div key={sub.id} style={{ border: "1px solid #ccc", borderRadius: "8px", padding: "15px" }}>
                <div style={{ display: "flex", justifyContent: "space-between" }}>
                  <span><strong>{sub.name}</strong></span>
                  <span>${sub.price.toFixed(2)}</span>
                </div>
                <div style={{ marginTop: "5px", fontSize: "0.9em", color: "#666" }}>
                  Status: {sub.status}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div>
        <h2>Quick Actions</h2>
        <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
          <button style={{ padding: "10px 15px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}>
            Add New Subscription
          </button>
          <button style={{ padding: "10px 15px", backgroundColor: "#28a745", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}>
            View All Subscriptions
          </button>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";

interface Subscription {
  id: number;
  name: string;
  category: string;
  amount: number;
  billingCycle: string;
  nextBillingDate: string;
}

export function SubscriptionsPage() {
  const [subscriptions, setSubscriptions] = useState<Subscription[]>([]);
  const [filteredSubscriptions, setFilteredSubscriptions] = useState<Subscription[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchSubscriptions();
  }, []);

  const fetchSubscriptions = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/subscriptions");
      if (!response.ok) {
        throw new Error(`Failed to fetch subscriptions: ${response.status}`);
      }
      const data = await response.json();
      setSubscriptions(data);
      setFilteredSubscriptions(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    let result = subscriptions;

    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      result = result.filter(sub => 
        sub.name.toLowerCase().includes(term) ||
        sub.category.toLowerCase().includes(term)
      );
    }

    if (categoryFilter !== "all") {
      result = result.filter(sub => sub.category === categoryFilter);
    }

    setFilteredSubscriptions(result);
  }, [searchTerm, categoryFilter, subscriptions]);

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/subscriptions/${id}`, {
        method: "DELETE",
      });
      if (!response.ok) {
        throw new Error(`Failed to delete subscription: ${response.status}`);
      }
      // Refresh the list after deletion
      fetchSubscriptions();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  const categories = Array.from(new Set(subscriptions.map(sub => sub.category)));

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>My Subscriptions</h1>

      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search subscriptions..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={categoryFilter}
          onChange={(e) => setCategoryFilter(e.target.value)}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="all">All Categories</option>
          {categories.map(category => (
            <option key={category} value={category}>{category}</option>
          ))}
        </select>
      </div>

      {filteredSubscriptions.length === 0 ? (
        <p style={{ textAlign: "center", padding: "20px" }}>No subscriptions found.</p>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          {filteredSubscriptions.map(sub => (
            <div 
              key={sub.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                display: "flex", 
                justifyContent: "space-between", 
                alignItems: "center",
                flexWrap: "wrap"
              }}
            >
              <div style={{ flex: 1, minWidth: "200px" }}>
                <h3 style={{ margin: "0 0 5px 0" }}>{sub.name}</h3>
                <p style={{ margin: "0 0 5px 0", color: "#666" }}>
                  {sub.category} • ${sub.amount.toFixed(2)} • {sub.billingCycle}
                </p>
                <p style={{ margin: "0", color: "#666" }}>
                  Next billing: {new Date(sub.nextBillingDate).toLocaleDateString()}
                </p>
              </div>
              <button 
                onClick={() => handleDelete(sub.id)}
                style={{ 
                  backgroundColor: "#ff4d4d", 
                  color: "white", 
                  border: "none", 
                  borderRadius: "4px", 
                  padding: "8px 12px", 
                  cursor: "pointer",
                  marginLeft: "10px"
                }}
              >
                Cancel
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

// Define types for our data structures
interface Task {
