import { useEffect, useState } from "react";

interface Parcel {
  id: string;
  trackingNumber: string;
  status: string;
  destination: string;
  weight: number;
  createdAt: string;
}

interface Statistics {
  totalParcels: number;
  pendingParcels: number;
  deliveredParcels: number;
}

export function AdminDashboard() {
  const [parcels, setParcels] = useState<Parcel[]>([]);
  const [stats, setStats] = useState<Statistics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchDashboardData() {
      try {
        const [parcelsResponse, statsResponse] = await Promise.all([
          fetch('/api/parcels'),
          fetch('/api/statistics')
        ]);

        if (!parcelsResponse.ok || !statsResponse.ok) {
          throw new Error('Failed to fetch dashboard data');
        }

        const parcelsData = await parcelsResponse.json();
        const statsData = await statsResponse.json();

        setParcels(parcelsData);
        setStats(statsData);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'An unknown error occurred');
        setLoading(false);
      }
    }

    fetchDashboardData();
  }, []);

  if (loading) {
    return <div style={{ textAlign: 'center', padding: '20px' }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: 'center', padding: '20px', color: 'red' }}>{error}</div>;
  }

  return (
    <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>Admin Dashboard</h1>

      {stats && (
        <div style={{ display: 'flex', justifyContent: 'space-around', flexWrap: 'wrap', marginBottom: '30px' }}>
          <div style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px', margin: '10px', minWidth: '200px' }}>
            <h2>Total Parcels</h2>
            <p style={{ fontSize: '24px', fontWeight: 'bold' }}>{stats.totalParcels}</p>
          </div>
          <div style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px', margin: '10px', minWidth: '200px' }}>
            <h2>Pending Parcels</h2>
            <p style={{ fontSize: '24px', fontWeight: 'bold' }}>{stats.pendingParcels}</p>
          </div>
          <div style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px', margin: '10px', minWidth: '200px' }}>
            <h2>Delivered Parcels</h2>
            <p style={{ fontSize: '24px', fontWeight: 'bold' }}>{stats.deliveredParcels}</p>
          </div>
        </div>
      )}

      <h2>Parcels Overview</h2>

      {parcels.length === 0 ? (
        <p style={{ textAlign: 'center', padding: '20px' }}>No parcels found.</p>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          {parcels.map(parcel => (
            <div key={parcel.id} style={{ border: '1px solid #ccc', borderRadius: '8px', padding: '15px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div>
                <strong>Tracking Number:</strong> {parcel.trackingNumber}<br />
                <strong>Status:</strong> {parcel.status}<br />
                <strong>Destination:</strong> {parcel.destination}<br />
                <strong>Weight:</strong> {parcel.weight} kg<br />
                <strong>Created:</strong> {new Date(parcel.createdAt).toLocaleDateString()}
              </div>
              <button 
                style={{ backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px', padding: '8px 12px', cursor: 'pointer' }}
                onClick={() => {
                  // In a real app, this would trigger an update to the parcel status
                  alert(`Update status for ${parcel.trackingNumber}`);
                }}
              >
                Update Status
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from "react";

interface LeaveRequest {
  id: number;
  employeeId: number;
  employeeName: string;
  startDate: string;
  endDate: string;
