  reason: string;
}

export function LeaveRequestsListPage() {
  const [leaveRequests, setLeaveRequests] = useState<LeaveRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [statusFilter, setStatusFilter] = useState<string>("");
  const [employeeFilter, setEmployeeFilter] = useState<string>("");
  const [startDateFilter, setStartDateFilter] = useState<string>("");
  const [endDateFilter, setEndDateFilter] = useState<string>("");

  useEffect(() => {
    fetchLeaveRequests();
  }, []);

  const fetchLeaveRequests = async () => {
    try {
      setLoading(true);
      // In a real app, this would be an API call
      // const response = await fetch('/api/leave-requests');
      // const data = await response.json();

      // Mock data for demonstration
      const mockData: LeaveRequest[] = [
        {
          id: 1,
          employeeId: 101,
          employeeName: "John Doe",
          startDate: "2023-05-15",
          endDate: "2023-05-17",
          status: "approved",
          reason: "Vacation"
        },
        {
          id: 2,
          employeeId: 102,
          employeeName: "Jane Smith",
          startDate: "2023-05-20",
          endDate: "2023-05-22",
          status: "pending",
          reason: "Sick leave"
        },
        {
          id: 3,
          employeeId: 103,
          employeeName: "Bob Johnson",
          startDate: "2023-05-10",
          endDate: "2023-05-12",
          status: "rejected",
          reason: "Personal day"
        }
      ];

      setLeaveRequests(mockData);
      setError(null);
    } catch (err) {
      setError("Failed to load leave requests");
    } finally {
      setLoading(false);
    }
  };

  const filteredRequests = leaveRequests.filter(request => {
    const matchesStatus = statusFilter === "" || request.status === statusFilter;
    const matchesEmployee = employeeFilter === "" || 
      request.employeeName.toLowerCase().includes(employeeFilter.toLowerCase());
    const matchesStartDate = startDateFilter === "" || 
      request.startDate >= startDateFilter;
    const matchesEndDate = endDateFilter === "" || 
      request.endDate <= endDateFilter;

    return matchesStatus && matchesEmployee && matchesStartDate && matchesEndDate;
  });

  const handleResetFilters = () => {
    setStatusFilter("");
    setEmployeeFilter("");
    setStartDateFilter("");
    setEndDateFilter("");
  };

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
