      <div style={{ marginBottom: "20px", display: "flex", flexDirection: "column", gap: "10px" }}>
        <input
          type="text"
          placeholder="Search by employee name"
          value={employeeFilter}
          onChange={(e) => setEmployeeFilter(e.target.value)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        />

        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
        >
          <option value="">All Statuses</option>
          <option value="pending">Pending</option>
          <option value="approved">Approved</option>
          <option value="rejected">Rejected</option>
        </select>

        <div style={{ display: "flex", gap: "10px" }}>
          <input
            type="date"
            value={startDateFilter}
            onChange={(e) => setStartDateFilter(e.target.value)}
            style={{ flex: 1, padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
          <input
            type="date"
            value={endDateFilter}
            onChange={(e) => setEndDateFilter(e.target.value)}
            style={{ flex: 1, padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
        </div>

        <button
          onClick={handleResetFilters}
          style={{ padding: "8px 16px", backgroundColor: "#f0f0f0", border: "none", borderRadius: "4px", cursor: "pointer" }}
        >
          Reset Filters
        </button>
      </div>

      {filteredRequests.length === 0 ? (
        <div style={{ textAlign: "center", padding: "20px" }}>
          No leave requests found.
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          {filteredRequests.map(request => (
            <div 
              key={request.id} 
              style={{ 
                border: "1px solid #ddd", 
                borderRadius: "8px", 
                padding: "15px", 
                backgroundColor: "#fafafa" 
              }}
            >
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "10px" }}>
                <h3 style={{ margin: 0 }}>{request.employeeName}</h3>
                <span style={{ 
                  backgroundColor: request.status === "approved" ? "#d4edda" : 
                                request.status === "rejected" ? "#f8d7da" : "#fff3cd", 
                  color: request.status === "approved" ? "#155724" : 
                         request.status === "rejected" ? "#721c24" : "#856404", 
                  padding: "4px 8px", 
                  borderRadius: "4px" 
                }}>
                  {request.status.charAt(0).toUpperCase() + request.status.slice(1)}
                </span>
              </div>

              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "10px" }}>
                <div>
                  <p style={{ margin: "5px 0" }}><strong>Start Date:</strong> {request.startDate}</p>
                  <p style={{ margin: "5px 0" }}><strong>End Date:</strong> {request.endDate}</p>
                </div>
                <div>
                  <p style={{ margin: "5px 0" }}><strong>Reason:</strong> {request.reason}</p>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

