import { useEffect, useState } from "react";

interface Truck {
  id: number;
  make: string;
  model: string;
  year: number;
  licensePlate: string;
}

export function TruckManagementPage() {
  const [trucks, setTrucks] = useState<Truck[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [newTruck, setNewTruck] = useState({
    make: "",
    model: "",
    year: "",
    licensePlate: ""
  });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchTrucks();
  }, []);

  const fetchTrucks = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/trucks");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setTrucks(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    } finally {
      setLoading(false);
    }
  };

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(e.target.value);
  };

  const handleAddTruck = (e: React.FormEvent) => {
    e.preventDefault();

    // In a real app, this would POST to an API endpoint
    // For now, we'll just simulate adding a truck
    const truckToAdd: Truck = {
      id: trucks.length + 1,
      make: newTruck.make,
      model: newTruck.model,
      year: parseInt(newTruck.year),
      licensePlate: newTruck.licensePlate
    };

    setTrucks([...trucks, truckToAdd]);

    // Reset form
    setNewTruck({
      make: "",
      model: "",
      year: "",
      licensePlate: ""
    });
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setNewTruck({
      ...newTruck,
      [name]: value
    });
  };

  const filteredTrucks = trucks.filter(truck =>
    truck.make.toLowerCase().includes(searchTerm.toLowerCase()) ||
    truck.model.toLowerCase().includes(searchTerm.toLowerCase()) ||
    truck.licensePlate.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;
  }

  if (error) {
    return <div style={{ textAlign: "center", padding: "20px", color: "red" }}>{error}</div>;
  }

  return (
    <div style={{
      maxWidth: "800px",
      margin: "0 auto",
      padding: "20px",
      fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
    }}>
      <h1 style={{ textAlign: "center" }}>Truck Management</h1>

      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search trucks..."
          value={searchTerm}
          onChange={handleSearchChange}
          style={{
            width: "100%",
            padding: "10px",
            borderRadius: "4px",
            border: "1px solid #ccc",
            fontSize: "16px"
          }}
        />
      </div>

      <div style={{ marginBottom: "30px" }}>
        <h2>Add New Truck</h2>
        <form onSubmit={handleAddTruck} style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          <input
            type="text"
            name="make"
            placeholder="Make"
            value={newTruck.make}
            onChange={handleInputChange}
            style={{
              padding: "10px",
              borderRadius: "4px",
              border: "1px solid #ccc",
              fontSize: "16px"
            }}
            required
          />
          <input
            type="text"
            name="model"
            placeholder="Model"
            value={newTruck.model}
            onChange={handleInputChange}
            style={{
              padding: "10px",
              borderRadius: "4px",
              border: "1px solid #ccc",
              fontSize: "16px"
            }}
            required
          />
          <input
            type="text"
            name="year"
            placeholder="Year"
            value={newTruck.year}
            onChange={handleInputChange}
