import { useEffect, useState } from "react";

interface Student {
  id: number;
  name: string;
  email: string;
  instrument: string;
  level: string;
}

export function StudentManagementPage() {
  const [students, setStudents] = useState<Student[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    instrument: "",
    level: "",
  });
  const [editingId, setEditingId] = useState<number | null>(null);

  // Fetch students
  useEffect(() => {
    const fetchStudents = async () => {
      try {
        const response = await fetch("/api/students");
        if (!response.ok) {
          throw new Error(`Failed to fetch students: ${response.status}`);
        }
        const data = await response.json();
        setStudents(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchStudents();
  }, []);

  // Filter students based on search term
  const filteredStudents = students.filter(
    student =>
      student.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      student.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
      student.instrument.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Handle form input changes
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const url = editingId 
        ? `/api/students/${editingId}`
        : "/api/students";

      const method = editingId ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        throw new Error(`Failed to ${editingId ? "update" : "create"} student: ${response.status}`);
      }

      // Refresh the student list
      const updatedResponse = await fetch("/api/students");
      if (!updatedResponse.ok) {
        throw new Error("Failed to refresh student list");
      }

      const updatedData = await updatedResponse.json();
      setStudents(updatedData);

      // Reset form
      setFormData({ name: "", email: "", instrument: "", level: "" });
      setEditingId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  // Handle edit
  const handleEdit = (student: Student) => {
    setFormData({
      name: student.name,
      email: student.email,
      instrument: student.instrument,
      level: student.level,
    });
    setEditingId(student.id);
  };

  // Handle delete
  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/students/${id}`, { method: "DELETE" });
      if (!response.ok) {
        throw new Error(`Failed to delete student: ${response.status}`);
      }

      // Refresh the student list
      const updatedResponse = await fetch("/api/students");
      if (!updatedResponse.ok) {
        throw new Error("Failed to refresh student list after deletion");
      }

      const updatedData = await updatedResponse.json();
      setStudents(updatedData);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Student Management</h1>

      {/* Search */}
      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search students..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{ width: "100%", padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
        />
      </div>

      {/* Form */}
      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", backgroundColor: "#f5f5f5", borderRadius: "8px" }}>
        <h2 style={{ marginTop: "0" }}>{editingId ? "Edit Student" : "Add New Student"}</h2>
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          <input
            type="text"
            name="name"
            placeholder="Name"
            value={formData.name}
            onChange={handleInputChange}
            required
            style={{ padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
          <input
            type="email"
            name="email"
            placeholder="Email"
            value={formData.email}
            onChange={handleInputChange}
            required
            style={{ padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
          <input
            type="text"
            name="instrument"
            placeholder="Instrument"
            value={formData.instrument}
            onChange={handleInputChange}
            required
            style={{ padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
          />
          <select
            name="level"
            value={formData.level}
            onChange={handleInputChange}
            required
            style={{ padding: "10px", borderRadius: "4px", border: "1px solid #ccc" }}
          >
            <option value="">Select Level</option>
            <option value="Beginner">Beginner</option>
            <option value="Intermediate">Intermediate</option>
            <option value="Advanced">Advanced</option>
          </select>
          <button 
            type="submit" 
            style={{ 
              padding: "10px 20px", 
              backgroundColor: "#007bff", 
              color: "white", 
              border: "none", 
              borderRadius: "4px", 
              cursor: "pointer" 
            }}
          >
            {editingId ? "Update Student" : "Add Student"}
          </button>
        </div>
      </form>

      {/* Student List */}
      <div>
        <h2>Students ({filteredStudents.length})</h2>
        {filteredStudents.length === 0 ? (
          <p style={{ textAlign: "center", padding: "20px" }}>No students found.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {filteredStudents.map(student => (
              <div 
                key={student.id} 
                style={{ 
                  padding: "15px", 
                  border: "1px solid #ddd", 
                  borderRadius: "8px", 
                  display: "flex", 
                  justifyContent: "space-between", 
                  alignItems: "center" 
                }}
              >
                <div>
                  <strong>{student.name}</strong><br />
                  {student.email}<br />
                  Instrument: {student.instrument}<br />
                  Level: {student.level}
                </div>
                <div style={{ display: "flex", gap: "5px" }}>
                  <button 
                    onClick={() => handleEdit(student)}
                    style={{ 
                      padding: "5px 10px", 
                      backgroundColor: "#ffc107", 
                      color: "black", 
                      border: "none", 
                      borderRadius: "4px", 
                      cursor: "pointer" 
                    }}
                  >
                    Edit
                  </button>
                  <button 
                    onClick={() => handleDelete(student.id)}
                    style={{ 
                      padding: "5px 10px", 
                      backgroundColor: "#dc3545", 
                      color: "white", 
                      border: "none", 
                      borderRadius: "4px", 
                      cursor: "pointer" 
                    }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

