import { useEffect, useState } from "react";

interface Employee {
  id: number;
  name: string;
  position: string;
  salary: number;
}

export function EmployeeManagement() {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Form state
  const [formData, setFormData] = useState({
    name: "",
    position: "",
    salary: ""
  });

  const [editingId, setEditingId] = useState<number | null>(null);

  // Fetch employees
  useEffect(() => {
    const fetchEmployees = async () => {
      try {
        const response = await fetch("/api/employees");
        if (!response.ok) {
          throw new Error(`Failed to fetch: ${response.status}`);
        }
        const data = await response.json();
        setEmployees(data);
        setLoading(false);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An unknown error occurred");
        setLoading(false);
      }
    };

    fetchEmployees();
  }, []);

  // Handle form input changes
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  // Submit form (add or edit)
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const url = editingId 
        ? `/api/employees/${editingId}`
        : "/api/employees";

      const method = editingId ? "PUT" : "POST";

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...formData,
          salary: Number(formData.salary)
        })
      });

      if (!response.ok) {
        throw new Error(`Failed to save: ${response.status}`);
      }

      // Refresh data
      const fetchEmployees = async () => {
        const response = await fetch("/api/employees");
        if (!response.ok) {
          throw new Error(`Failed to fetch: ${response.status}`);
        }
        const data = await response.json();
        setEmployees(data);
        setLoading(false);
      };

      fetchEmployees();

      // Reset form
      setFormData({ name: "", position: "", salary: "" });
      setEditingId(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  // Delete employee
  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/employees/${id}`, { method: "DELETE" });
      if (!response.ok) {
        throw new Error(`Failed to delete: ${response.status}`);
      }

      // Refresh data
      const fetchEmployees = async () => {
        const response = await fetch("/api/employees");
        if (!response.ok) {
          throw new Error(`Failed to fetch: ${response.status}`);
        }
        const data = await response.json();
        setEmployees(data);
        setLoading(false);
      };

      fetchEmployees();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An unknown error occurred");
    }
  };

  // Edit employee
  const handleEdit = (employee: Employee) => {
    setFormData({
      name: employee.name,
      position: employee.position,
      salary: employee.salary.toString()
    });
    setEditingId(employee.id);
  };

  // Cancel edit
  const handleCancel = () => {
    setFormData({ name: "", position: "", salary: "" });
    setEditingId(null);
  };

  if (loading) return <div style={{ textAlign: "center", padding: "20px" }}>Loading...</div>;

  if (error) return <div style={{ color: "red", textAlign: "center", padding: "20px" }}>{error}</div>;

  return (
    <div style={{ maxWidth: "800px", margin: "0 auto", padding: "20px", fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <h1 style={{ textAlign: "center" }}>Employee Management</h1>

      {/* Add/Edit Form */}
      <form onSubmit={handleSubmit} style={{ marginBottom: "30px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px" }}>
        <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
          <input
            type="text"
            name="name"
            placeholder="Name"
            value={formData.name}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
          />
          <input
            type="text"
            name="position"
            placeholder="Position"
            value={formData.position}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
          />
          <input
            type="number"
            name="salary"
            placeholder="Salary"
            value={formData.salary}
            onChange={handleInputChange}
            style={{ width: "100%", padding: "8px", boxSizing: "border-box" }}
          />
          <div style={{ display: "flex", gap: "10px" }}>
            <button 
              type="submit" 
              style={{ flex: 1, padding: "10px", backgroundColor: "#007bff", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
            >
              {editingId ? "Update Employee" : "Add Employee"}
            </button>
            {editingId && (
              <button 
                type="button" 
                onClick={handleCancel}
                style={{ flex: 1, padding: "10px", backgroundColor: "#6c757d", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
              >
                Cancel
              </button>
            )}
          </div>
        </div>
      </form>

      {/* Employee List */}
      <div>
        <h2>Employee Records</h2>
        {employees.length === 0 ? (
          <p style={{ textAlign: "center", padding: "20px" }}>No employees found.</p>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {employees.map(employee => (
              <div 
                key={employee.id} 
                style={{ 
                  border: "1px solid #ccc", 
                  borderRadius: "8px", 
                  padding: "15px", 
                  display: "flex", 
                  justifyContent: "space-between", 
                  alignItems: "center",
                  flexWrap: "wrap"
                }}
              >
                <div style={{ flex: 1, minWidth: "200px" }}>
                  <strong>{employee.name}</strong><br />
                  {employee.position}<br />
                  Salary: ${employee.salary.toLocaleString()}
                </div>
                <div style={{ display: "flex", gap: "5px", flexShrink: 0 }}>
                  <button 
                    onClick={() => handleEdit(employee)}
                    style={{ padding: "5px 10px", backgroundColor: "#17a2b8", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
                  >
                    Edit
                  </button>
                  <button 
                    onClick={() => handleDelete(employee.id)}
                    style={{ padding: "5px 10px", backgroundColor: "#dc3545", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

