                  <strong>{record.employeeName}</strong>
                  <p>Hours Worked: {record.hoursWorked}</p>
                  <p>Hourly Rate: ${record.hourlyRate.toFixed(2)}</p>
                  <p>Gross Pay: ${record.grossPay.toFixed(2)}</p>
                  <p>Net Pay: ${record.netPay.toFixed(2)}</p>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <p><strong>Pay Date:</strong> {new Date(record.payDate).toLocaleDateString()}</p>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div style={{ marginTop: '30px' }}>
        <h2>Process New Payroll</h2>
        <form onSubmit={(e) => {
          e.preventDefault();
          // In a real app, this would submit to an API
          alert('New payroll processed!');
          fetchPayrollRecords();
        }}>
          <div style={{ marginBottom: '10px' }}>
            <label htmlFor="employeeId" style={{ display: 'block', marginBottom: '5px' }}>Employee ID</label>
            <input
              type="text"
              id="employeeId"
              style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
              required
            />
          </div>

          <div style={{ marginBottom: '10px' }}>
            <label htmlFor="hoursWorked" style={{ display: 'block', marginBottom: '5px' }}>Hours Worked</label>
            <input
              type="number"
              id="hoursWorked"
              style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
              required
            />
          </div>

          <div style={{ marginBottom: '10px' }}>
            <label htmlFor="hourlyRate" style={{ display: 'block', marginBottom: '5px' }}>Hourly Rate</label>
            <input
              type="number"
              id="hourlyRate"
              step="0.01"
              style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #ccc' }}
              required
            />
          </div>

          <button 
            type="submit" 
            style={{ 
              backgroundColor: '#007bff', 
              color: 'white', 
              border: 'none', 
              padding: '10px 20px', 
              borderRadius: '4px', 
