  useEffect(() => {
    fetch('/api/reservations-api/')
      .then(response => response.json())
      .then(data => setReservations(data));
  }, []);

  const handleCreateReservation = () => {
    if (!driverId || !timeSlot) return;

    fetch('/api/reservations-api/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        driverId,
        timeSlot,
        status
      })
    })
      .then(response => response.json())
      .then(newReservation => {
        setReservations([...reservations, newReservation]);
        setDriverId('');
        setTimeSlot('');
      });
  };

  const handleDeleteReservation = (id: string) => {
    fetch(`/api/reservations-api/${id}`, {
      method: 'DELETE'
    })
      .then(() => {
        setReservations(reservations.filter(r => r.id !== id));
      });
  };

  return (
    <div>
      <h2>Reserve a Spot</h2>
      <div>
        <input
          type="text"
          placeholder="Driver ID"
          value={driverId}
          onChange={(e) => setDriverId(e.target.value)}
        />
        <input
          type="text"
          placeholder="Time Slot"
          value={timeSlot}
          onChange={(e) => setTimeSlot(e.target.value)}
        />
        <select value={status} onChange={(e) => setStatus(e.target.value)}>
          <option value="active">Active</option>
          <option value="completed">Completed</option>
          <option value="cancelled">Cancelled</option>
        </select>
        <button onClick={handleCreateReservation}>Reserve</button>
      </div>

      <h2>Your Bookings</h2>
      <ul>
        {reservations.map(reservation => (
          <li key={reservation.id}>
            {reservation.timeSlot} - {reservation.status}
            <button onClick={() => handleDeleteReservation(reservation.id)}>Cancel</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface CoOpMember {
  id: number;
  name: string;
  email: string;
  energy_quota: number;
}

export function AdminAllocationPanel() {
  const [members, setMembers] = useState<CoOpMember[]>([]);
  const [newMember, setNewMember] = useState<Omit<CoOpMember, 'id'>>({ 
    name: '', 
    email: '', 
    energy_quota: 0 
  });
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState<Partial<CoOpMember>>({});

  useEffect(() => {
    fetch('/api/co-op-allocation-api/')
      .then(res => res.json())
      .then(data => setMembers(data));
  }, []);

  const handleAddMember = () => {
    fetch('/api/co-op-allocation-api/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(newMember)
    })
      .then(res => res.json())
      .then(member => {
        setMembers([...members, member]);
        setNewMember({ name: '', email: '', energy_quota: 0 });
      });
  };

  const handleUpdateMember = () => {
    if (editingId === null) return;

    fetch(`/api/co-op-allocation-api/${editingId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: editForm.name,
        energy_quota: editForm.energy_quota
      })
    })
      .then(res => res.json())
      .then(updatedMember => {
        setMembers(members.map(m => m.id === editingId ? updatedMember : m));
        setEditingId(null);
        setEditForm({});
      });
  };

  const handleDeleteMember = (id: number) => {
    fetch(`/api/co-op-allocation-api/${id}`, { method: 'DELETE' })
      .then(() => setMembers(members.filter(m => m.id !== id)));
  };

  return (
    <div>
      <h1>Admin Allocation Panel</h1>

      <h2>Add New Member</h2>
      <div>
        <input
          type="text"
          placeholder="Name"
          value={newMember.name}
          onChange={e => setNewMember({...newMember, name: e.target.value})}
        />
        <input
          type="email"
          placeholder="Email"
          value={newMember.email}
          onChange={e => setNewMember({...newMember, email: e.target.value})}
        />
        <input
          type="number"
          placeholder="Energy Quota"
          value={newMember.energy_quota}
          onChange={e => setNewMember({...newMember, energy_quota: Number(e.target.value)})}
        />
        <button onClick={handleAddMember}>Add Member</button>
      </div>

      <h2>Manage Members</h2>
      <ul>
        {members.map(member => (
          <li key={member.id}>
            {editingId === member.id ? (
              <div>
                <input
                  type="text"
                  value={editForm.name || ''}
                  onChange={e => setEditForm({...editForm, name: e.target.value})}
                />
                <input
                  type="number"
                  value={editForm.energy_quota || 0}
                  onChange={e => setEditForm({...editForm, energy_quota: Number(e.target.value)})}
                />
                <button onClick={handleUpdateMember}>Save</button>
                <button onClick={() => setEditingId(null)}>Cancel</button>
              </div>
            ) : (
              <div>
                <span>{member.name} ({member.email}): {member.energy_quota} kWh</span>
                <button onClick={() => {
                  setEditingId(member.id);
                  setEditForm({ name: member.name, energy_quota: member.energy_quota });
                }}>Edit</button>
                <button onClick={() => handleDeleteMember(member.id)}>Delete</button>
              </div>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

