import { useState, useEffect } from 'react';

interface Keg {
  id: number;
  style: string;
  quantity: number;
}

export function InventoryDashboard() {
  const [kegs, setKegs] = useState<Keg[]>([]);
  const [newKegStyle, setNewKegStyle] = useState('');
  const [newKegQuantity, setNewKegQuantity] = useState('');
  const [editingKegId, setEditingKegId] = useState<number | null>(null);
  const [editStyle, setEditStyle] = useState('');
  const [editQuantity, setEditQuantity] = useState('');

  useEffect(() => {
    fetch('/api/inventory-api/')
      .then(res => res.json())
      .then(data => setKegs(data));
  }, []);

  const handleAddKeg = () => {
    if (!newKegStyle || !newKegQuantity) return;

    fetch('/api/inventory-api/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        style: newKegStyle,
        quantity: Number(newKegQuantity)
      })
    })
    .then(res => res.json())
    .then(addedKeg => {
      setKegs([...kegs, addedKeg]);
      setNewKegStyle('');
      setNewKegQuantity('');
    });
  };

  const handleUpdateKeg = () => {
    if (editingKegId === null || !editStyle || !editQuantity) return;

    fetch(`/api/inventory-api/${editingKegId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        style: editStyle,
        quantity: Number(editQuantity)
      })
    })
    .then(res => res.json())
    .then(updatedKeg => {
      setKegs(kegs.map(k => k.id === editingKegId ? updatedKeg : k));
      setEditingKegId(null);
      setEditStyle('');
      setEditQuantity('');
    });
  };

  const handleDeleteKeg = (id: number) => {
    fetch(`/api/inventory-api/${id}`, { method: 'DELETE' })
      .then(() => setKegs(kegs.filter(k => k.id !== id)));
  };

  return (
    <div>
      <h1>Brewery Keg Inventory</h1>

      <div>
        <h2>Add New Keg</h2>
        <input
          type="text"
          placeholder="Keg Style"
          value={newKegStyle}
          onChange={(e) => setNewKegStyle(e.target.value)}
        />
        <input
          type="number"
          placeholder="Quantity"
          value={newKegQuantity}
          onChange={(e) => setNewKegQuantity(e.target.value)}
        />
        <button onClick={handleAddKeg}>Log Fill</button>
      </div>

      <div>
        <h2>Current Stock</h2>
        <ul>
          {kegs.map(keg => (
            <li key={keg.id}>
              {editingKegId === keg.id ? (
                <>
                  <input
                    type="text"
                    value={editStyle}
                    onChange={(e) => setEditStyle(e.target.value)}
                  />
                  <input
                    type="number"
                    value={editQuantity}
                    onChange={(e) => setEditQuantity(e.target.value)}
                  />
                  <button onClick={handleUpdateKeg}>Save</button>
                </>
              ) : (
                <>
                  {keg.style}: {keg.quantity} units
                  <button onClick={() => {
                    setEditingKegId(keg.id);
                    setEditStyle(keg.style);
                    setEditQuantity(keg.quantity.toString());
                  }}>Edit</button>
                  <button onClick={() => handleDeleteKeg(keg.id)}>Remove</button>
                </>
              )}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

