  date: string;
}

interface BookingForm {
  docentId: number;
  exhibitId: number;
  date: string;
}

export function TourBookingWidget() {
  const [tours, setTours] = useState<Tour[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [formData, setFormData] = useState<BookingForm>({
    docentId: 0,
    exhibitId: 0,
    date: '',
  });

  useEffect(() => {
    fetch('/api/tours-api/')
      .then(res => res.json())
      .then(data => {
        setTours(data);
        setLoading(false);
      })
      .catch(err => {
        setError('Failed to load tours');
        setLoading(false);
      });
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: name === 'docentId' || name === 'exhibitId' ? Number(value) : value,
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    fetch('/api/tours-api/', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(formData),
    })
      .then(res => res.json())
      .then(newTour => {
        setTours([...tours, newTour]);
        setFormData({ docentId: 0, exhibitId: 0, date: '' });
      })
      .catch(err => {
        setError('Failed to book tour');
      });
  };

  if (loading) return <div>Loading tours...</div>;
  if (error) return <div>Error: {error}</div>;

  return (
    <div>
      <h2>Book a Tour</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="docentId">Docent ID:</label>
          <input
            type="number"
            id="docentId"
            name="docentId"
            value={formData.docentId}
            onChange={handleInputChange}
            required
          />
        </div>
        <div>
          <label htmlFor="exhibitId">Exhibit ID:</label>
          <input
            type="number"
            id="exhibitId"
            name="exhibitId"
            value={formData.exhibitId}
            onChange={handleInputChange}
            required
          />
        </div>
        <div>
          <label htmlFor="date">Date:</label>
          <input
            type="date"
            id="date"
            name="date"
            value={formData.date}
            onChange={handleInputChange}
            required
          />
        </div>
        <button type="submit">Book Tour</button>
      </form>

      <h3>Available Tours</h3>
      <ul>
        {tours.map(tour => (
          <li key={tour.id}>
            Tour #{tour.id}: Docent {tour.docentId}, Exhibit {tour.exhibitId} on {tour.date}
          </li>
        ))}
      </ul>
    </div>
  );
}

