import { useState, useEffect } from 'react';

interface Car {
  id: number;
  make: string;
  model: string;
  year: number;
  color: string;
  dailyRate: number;
}

interface BookingForm {
  carId: number | null;
  startDate: string;
  endDate: string;
}

export function CarListPage() {
  const [cars, setCars] = useState<Car[]>([]);
  const [filteredCars, setFilteredCars] = useState<Car[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filters, setFilters] = useState({
    make: '',
    model: '',
    minYear: '',
    maxYear: '',
    minDailyRate: '',
    maxDailyRate: ''
  });
  const [bookingForm, setBookingForm] = useState<BookingForm>({
    carId: null,
    startDate: '',
    endDate: ''
  });

  useEffect(() => {
    fetchCars();
  }, []);

  useEffect(() => {
    applyFilters();
  }, [cars, filters]);

  const fetchCars = async () => {
    try {
      const response = await fetch('/api/car-management-api');
      if (!response.ok) {
        throw new Error('Failed to fetch cars');
      }
      const data = await response.json();
      setCars(data);
      setFilteredCars(data);
    } catch (err) {
      setError('Error fetching cars');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const applyFilters = () => {
    let result = [...cars];

    if (filters.make) {
      result = result.filter(car => 
        car.make.toLowerCase().includes(filters.make.toLowerCase())
      );
    }

    if (filters.model) {
      result = result.filter(car => 
        car.model.toLowerCase().includes(filters.model.toLowerCase())
      );
    }

    if (filters.minYear) {
      result = result.filter(car => car.year >= parseInt(filters.minYear));
    }

    if (filters.maxYear) {
      result = result.filter(car => car.year <= parseInt(filters.maxYear));
    }

    if (filters.minDailyRate) {
      result = result.filter(car => car.dailyRate >= parseFloat(filters.minDailyRate));
    }

    if (filters.maxDailyRate) {
      result = result.filter(car => car.dailyRate <= parseFloat(filters.maxDailyRate));
    }

    setFilteredCars(result);
  };

  const handleFilterChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFilters(prev => ({ ...prev, [name]: value }));
  };

  const handleBookingChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setBookingForm(prev => ({ ...prev, [name]: value }));
  };

  const handleBookCar = async (carId: number) => {
    if (!bookingForm.startDate || !bookingForm.endDate) {
      alert('Please enter start and end dates');
      return;
    }

    try {
      const response = await fetch('/api/booking-management-api/bookings', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          carId,
          startDate: bookingForm.startDate,
          endDate: bookingForm.endDate
        })
      });

      if (!response.ok) {
        throw new Error('Failed to book car');
      }

      alert('Car booked successfully!');
      setBookingForm({ carId: null, startDate: '', endDate: '' });
    } catch (err) {
      setError('Error booking car');
      console.error(err);
    }
  };

  if (loading) return <div>Loading cars...</div>;
  if (error) return <div>Error: {error}</div>;

  return (
    <div className="car-list-page">
      <h1>Available Cars</h1>

      <div className="filters">
        <h2>Filter Cars</h2>
        <input
          type="text"
          name="make"
          placeholder="Make"
          value={filters.make}
          onChange={handleFilterChange}
        />
        <input
          type="text"
          name="model"
          placeholder="Model"
          value={filters.model}
          onChange={handleFilterChange}
        />
        <input
          type="number"
          name="minYear"
          placeholder="Min Year"
          value={filters.minYear}
          onChange={handleFilterChange}
        />
        <input
          type="number"
          name="maxYear"
          placeholder="Max Year"
          value={filters.maxYear}
          onChange={handleFilterChange}
        />
        <input
          type="number"
          name="minDailyRate"
          placeholder="Min Daily Rate"
          value={filters.minDailyRate}
          onChange={handleFilterChange}
        />
        <input
          type="number"
          name="maxDailyRate"
          placeholder="Max Daily Rate"
          value={filters.maxDailyRate}
          onChange={handleFilterChange}
        />
      </div>

      <div className="booking-form">
        <h2>Book a Car</h2>
        <input
          type="date"
          name="startDate"
          placeholder="Start Date"
          value={bookingForm.startDate}
          onChange={handleBookingChange}
        />
        <input
          type="date"
          name="endDate"
          placeholder="End Date"
          value={bookingForm.endDate}
          onChange={handleBookingChange}
        />
      </div>

      <div className="car-list">
        {filteredCars.length === 0 ? (
          <p>No cars found matching your criteria.</p>
        ) : (
          filteredCars.map(car => (
            <div key={car.id} className="car-card">
              <h3>{car.make} {car.model}</h3>
              <p>Year: {car.year}</p>
              <p>Color: {car.color}</p>
              <p>Daily Rate: ${car.dailyRate}</p>
              <button onClick={() => handleBookCar(car.id)}>Book Now</button>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Appointment {
  id: number;
  patientId: number;
  date: string;
  time: string;
  service: string;
}

interface Patient {
  id: number;
  name: string;
  email: string;
  phone: string;
  medicalHistory: string;
}

export function AppointmentScheduler() {
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [patients, setPatients] = useState<Patient[]>([]);
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [showForm, setShowForm] = useState<boolean>(false);

  // Form state
  const [formData, setFormData] = useState({
    patientId: '',
    date: selectedDate,
    time: '',
    service: ''
  });

  // Fetch appointments and patients
  useEffect(() => {
    fetch('/api/appointment-service/appointments')
      .then(res => res.json())
      .then(data => setAppointments(data));

    fetch('/api/patient-service/patients')
      .then(res => res.json())
      .then(data => setPatients(data));
  }, []);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    fetch('/api/appointment-service/appointments', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        patientId: Number(formData.patientId),
        date: formData.date,
        time: formData.time,
        service: formData.service
      })
    })
    .then(res => res.json())
    .then(newAppointment => {
      setAppointments(prev => [...prev, newAppointment]);
      setShowForm(false);
      setFormData({
        patientId: '',
        date: selectedDate,
        time: '',
        service: ''
      });
    });
  };

  const handleUpdate = (id: number, updatedFields: Partial<Appointment>) => {
    fetch(`/api/appointment-service/appointments/${id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        patientId: updatedFields.patientId || 0,
        date: updatedFields.date || '',
        time: updatedFields.time || '',
        service: updatedFields.service || ''
      })
    })
    .then(res => res.json())
    .then(updatedAppointment => {
      setAppointments(prev => 
        prev.map(app => app.id === id ? updatedAppointment : app)
      );
    });
  };

  const handleDelete = (id: number) => {
    fetch(`/api/appointment-service/appointments/${id}`, {
      method: 'DELETE'
    })
    .then(() => {
      setAppointments(prev => prev.filter(app => app.id !== id));
    });
  };

  const getFilteredAppointments = () => {
    return appointments.filter(app => app.date === selectedDate);
  };

  return (
    <div className="appointment-scheduler">
      <h1>Dental Clinic Appointment Scheduler</h1>

      <div className="calendar-controls">
        <input 
          type="date" 
          value={selectedDate}
          onChange={(e) => setSelectedDate(e.target.value)}
        />
        <button onClick={() => setShowForm(true)}>Add New Appointment</button>
      </div>

      {showForm && (
        <form onSubmit={handleSubmit} className="appointment-form">
          <h2>Add New Appointment</h2>
          <select 
            name="patientId" 
            value={formData.patientId}
            onChange={handleInputChange}
            required
          >
            <option value="">Select Patient</option>
            {patients.map(patient => (
              <option key={patient.id} value={patient.id}>{patient.name}</option>
            ))}
          </select>

          <input 
            type="date" 
            name="date" 
            value={formData.date}
            onChange={handleInputChange}
            required
          />

          <input 
            type="time" 
            name="time" 
            value={formData.time}
            onChange={handleInputChange}
            required
          />

          <input 
            type="text" 
            name="service" 
            value={formData.service}
            onChange={handleInputChange}
            placeholder="Service"
            required
          />

          <button type="submit">Save Appointment</button>
          <button type="button" onClick={() => setShowForm(false)}>Cancel</button>
        </form>
      )}

      <div className="appointments-list">
        <h2>Appointments for {selectedDate}</h2>
        {getFilteredAppointments().length === 0 ? (
          <p>No appointments scheduled for this date.</p>
        ) : (
          <ul>
            {getFilteredAppointments().map(appointment => (
              <li key={appointment.id} className="appointment-item">
                <span>{appointment.time} - {appointment.service}</span>
                <div className="appointment-actions">
                  <button onClick={() => handleDelete(appointment.id)}>Delete</button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

