import { useState, useEffect } from 'react';

interface Batch {
  id: number;
  name: string;
  startDate: string;
  endDate: string;
  maxStudents: number;
}

export function BatchManagementPage() {
  const [batches, setBatches] = useState<Batch[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [newBatch, setNewBatch] = useState({
    name: '',
    startDate: '',
    endDate: '',
    maxStudents: 0
  });
  const [editingBatchId, setEditingBatchId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState({
    name: '',
    startDate: '',
    endDate: '',
    maxStudents: 0
  });

  // Fetch batches on component mount
  useEffect(() => {
    fetchBatches();
  }, []);

  const fetchBatches = async () => {
    try {
      const response = await fetch('/api/batch-api/batches');
      const data = await response.json();
      setBatches(data);
    } catch (error) {
      console.error('Failed to fetch batches:', error);
    }
  };

  const handleCreateBatch = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch('/api/batch-api/batches', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(newBatch)
      });
      if (response.ok) {
        const createdBatch = await response.json();
        setBatches([...batches, createdBatch]);
        setNewBatch({
          name: '',
          startDate: '',
          endDate: '',
          maxStudents: 0
        });
      }
    } catch (error) {
      console.error('Failed to create batch:', error);
    }
  };

  const handleUpdateBatch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingBatchId === null) return;
    try {
      const response = await fetch(`/api/batch-api/batches/${editingBatchId}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(editForm)
      });
      if (response.ok) {
        const updatedBatch = await response.json();
        setBatches(batches.map(batch => batch.id === editingBatchId ? updatedBatch : batch));
        setEditingBatchId(null);
      }
    } catch (error) {
      console.error('Failed to update batch:', error);
    }
  };

  const handleDeleteBatch = async (id: number) => {
    try {
      const response = await fetch(`/api/batch-api/batches/${id}`, {
        method: 'DELETE'
      });
      if (response.ok) {
        setBatches(batches.filter(batch => batch.id !== id));
      }
    } catch (error) {
      console.error('Failed to delete batch:', error);
    }
  };

  const filteredBatches = batches.filter(batch => 
    batch.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="batch-management-page">
      <h1>Batch Management</h1>

      {/* Create New Batch Form */}
      <form onSubmit={handleCreateBatch}>
        <h2>Create New Batch</h2>
        <input
          type="text"
          placeholder="Batch Name"
          value={newBatch.name}
          onChange={(e) => setNewBatch({...newBatch, name: e.target.value})}
          required
        />
        <input
          type="date"
          value={newBatch.startDate}
          onChange={(e) => setNewBatch({...newBatch, startDate: e.target.value})}
          required
        />
        <input
          type="date"
          value={newBatch.endDate}
          onChange={(e) => setNewBatch({...newBatch, endDate: e.target.value})}
          required
        />
        <input
          type="number"
          placeholder="Max Students"
          value={newBatch.maxStudents || ''}
          onChange={(e) => setNewBatch({...newBatch, maxStudents: Number(e.target.value)})}
          required
        />
        <button type="submit">Create Batch</button>
      </form>

      {/* Search Bar */}
      <input
        type="text"
        placeholder="Search Batches..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />

      {/* Batch List */}
      <div className="batch-list">
        {filteredBatches.length > 0 ? (
          filteredBatches.map(batch => (
            <div key={batch.id} className="batch-item">
              {editingBatchId === batch.id ? (
                <form onSubmit={handleUpdateBatch}>
                  <input
                    type="text"
                    value={editForm.name}
                    onChange={(e) => setEditForm({...editForm, name: e.target.value})}
                    required
                  />
                  <input
                    type="date"
                    value={editForm.startDate}
                    onChange={(e) => setEditForm({...editForm, startDate: e.target.value})}
                    required
                  />
                  <input
                    type="date"
                    value={editForm.endDate}
                    onChange={(e) => setEditForm({...editForm, endDate: e.target.value})}
                    required
                  />
                  <input
                    type="number"
                    value={editForm.maxStudents || ''}
                    onChange={(e) => setEditForm({...editForm, maxStudents: Number(e.target.value)})}
                    required
                  />
                  <button type="submit">Save</button>
                  <button type="button" onClick={() => setEditingBatchId(null)}>Cancel</button>
                </form>
              ) : (
                <>
                  <h3>{batch.name}</h3>
                  <p>Start Date: {batch.startDate}</p>
                  <p>End Date: {batch.endDate}</p>
                  <p>Max Students: {batch.maxStudents}</p>
                  <button onClick={() => {
                    setEditingBatchId(batch.id);
                    setEditForm({
                      name: batch.name,
                      startDate: batch.startDate,
                      endDate: batch.endDate,
                      maxStudents: batch.maxStudents
                    });
                  }}>Edit</button>
                  <button onClick={() => handleDeleteBatch(batch.id)}>Delete</button>
                </>
              )}
            </div>
          ))
        ) : (
          <p>No batches found.</p>
        )}
      </div>
    </div>
  );
}

