export function MeasurementTrackingPage() {
  const [measurements, setMeasurements] = useState<Measurement[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCustomerId, setSelectedCustomerId] = useState<number | null>(null);
  const [newMeasurement, setNewMeasurement] = useState({
    customerId: '',
    chest: '',
    waist: '',
    hips: '',
    sleeve: '',
    length: ''
  });
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState({
    customerId: '',
    chest: '',
    waist: '',
    hips: '',
    sleeve: '',
    length: ''
  });

  // Fetch customers and measurements
  useEffect(() => {
    fetch('/api/customer-api')
      .then(res => res.json())
      .then(data => setCustomers(data));

    fetch('/api/measurement-api')
      .then(res => res.json())
      .then(data => setMeasurements(data));
  }, []);

  // Filter measurements based on search term
  const filteredMeasurements = measurements.filter(measurement => {
    const customer = customers.find(c => c.id === measurement.customerId);
    return customer?.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
           measurement.chest.toString().includes(searchTerm) ||
           measurement.waist.toString().includes(searchTerm);
  });

  const handleAddMeasurement = () => {
    if (!newMeasurement.customerId) return;

    fetch('/api/measurement-api', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        customerId: Number(newMeasurement.customerId),
        chest: Number(newMeasurement.chest),
        waist: Number(newMeasurement.waist),
        hips: Number(newMeasurement.hips),
        sleeve: Number(newMeasurement.sleeve),
        length: Number(newMeasurement.length)
      })
    })
    .then(res => res.json())
    .then(data => {
      setMeasurements([...measurements, data]);
      setNewMeasurement({
        customerId: '',
        chest: '',
        waist: '',
        hips: '',
        sleeve: '',
        length: ''
      });
    });
  };

  const handleUpdateMeasurement = () => {
    if (editingId === null) return;

    fetch(`/api/measurement-api/${editingId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        customerId: Number(editForm.customerId),
        chest: Number(editForm.chest),
        waist: Number(editForm.waist),
        hips: Number(editForm.hips),
        sleeve: Number(editForm.sleeve),
        length: Number(editForm.length)
      })
    })
    .then(res => res.json())
    .then(data => {
      setMeasurements(measurements.map(m => m.id === editingId ? data : m));
      setEditingId(null);
    });
  };

  const handleDeleteMeasurement = (id: number) => {
    fetch(`/api/measurement-api/${id}`, {
      method: 'DELETE'
    })
    .then(() => {
      setMeasurements(measurements.filter(m => m.id !== id));
    });
  };

  return (
    <div className="measurement-tracking-page">
      <h1>Measurement Tracking</h1>

      <div className="add-measurement-section">
        <h2>Add New Measurement</h2>
        <div className="form-group">
          <label>Customer:</label>
          <select
            value={newMeasurement.customerId}
            onChange={(e) => setNewMeasurement({...newMeasurement, customerId: e.target.value})}
          >
            <option value="">Select Customer</option>
            {customers.map(customer => (
              <option key={customer.id} value={customer.id}>{customer.name}</option>
            ))}
          </select>
        </div>

        <div className="form-group">
          <label>Chest (cm):</label>
          <input
            type="number"
            value={newMeasurement.chest}
            onChange={(e) => setNewMeasurement({...newMeasurement, chest: e.target.value})}
          />
        </div>

        <div className="form-group">
          <label>Waist (cm):</label>
          <input
            type="number"
            value={newMeasurement.waist}
            onChange={(e) => setNewMeasurement({...newMeasurement, waist: e.target.value})}
          />
        </div>

        <div className="form-group">
          <label>Hips (cm):</label>
          <input
            type="number"
            value={newMeasurement.hips}
            onChange={(e) => setNewMeasurement({...newMeasurement, hips: e.target.value})}
          />
        </div>

        <div className="form-group">
          <label>Sleeve (cm):</label>
          <input
            type="number"
            value={newMeasurement.sleeve}
            onChange={(e) => setNewMeasurement({...newMeasurement, sleeve: e.target.value})}
          />
        </div>

        <div className="form-group">
          <label>Length (cm):</label>
          <input
            type="number"
            value={newMeasurement.length}
            onChange={(e) => setNewMeasurement({...newMeasurement, length: e.target.value})}
          />
        </div>

        <button onClick={handleAddMeasurement}>Add Measurement</button>
      </div>

      <div className="search-section">
        <h2>Search Measurements</h2>
        <input
          type="text"
          placeholder="Search by customer name or measurement..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="measurements-list">
        <h2>Measurement History</h2>
        <table>
          <thead>
            <tr>
              <th>Customer</th>
              <th>Chest (cm)</th>
              <th>Waist (cm)</th>
              <th>Hips (cm)</th>
              <th>Sleeve (cm)</th>
              <th>Length (cm)</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredMeasurements.map(measurement => {
              const customer = customers.find(c => c.id === measurement.customerId);
              return (
                <tr key={measurement.id}>
                  <td>{customer?.name || 'Unknown Customer'}</td>
                  <td>{measurement.chest}</td>
                  <td>{measurement.waist}</td>
                  <td>{measurement.hips}</td>
                  <td>{measurement.sleeve}</td>
                  <td>{measurement.length}</td>
                  <td>
                    <button onClick={() => {
                      setEditingId(measurement.id);
                      setEditForm({
                        customerId: measurement.customerId.toString(),
                        chest: measurement.chest.toString(),
                        waist: measurement.waist.toString(),
                        hips: measurement.hips.toString(),
                        sleeve: measurement.sleeve.toString(),
                        length: measurement.length.toString()
                      });
                    }}>Edit</button>
                    <button onClick={() => handleDeleteMeasurement(measurement.id)}>Delete</button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {editingId !== null && (
        <div className="edit-measurement-section">
          <h2>Edit Measurement</h2>
          <div className="form-group">
            <label>Customer:</label>
            <select
              value={editForm.customerId}
              onChange={(e) => setEditForm({...editForm, customerId: e.target.value})}
            >
              <option value="">Select Customer</option>
              {customers.map(customer => (
                <option key={customer.id} value={customer.id}>{customer.name}</option>
              ))}
            </select>
          </div>

          <div className="form-group">
            <label>Chest (cm):</label>
            <input
              type="number"
              value={editForm.chest}
              onChange={(e) => setEditForm({...editForm, chest: e.target.value})}
            />
          </div>

          <div className="form-group">
            <label>Waist (cm):</label>
            <input
              type="number"
              value={editForm.waist}
              onChange={(e) => setEditForm({...editForm, waist: e.target.value})}
            />
          </div>

          <div className="form-group">
            <label>Hips (cm):</label>
            <input
              type="number"
              value={editForm.hips}
              onChange={(e) => setEditForm({...editForm, hips: e.target.value})}
            />
          </div>

          <div className="form-group">
            <label>Sleeve (cm):</label>
            <input
              type="number"
              value={editForm.sleeve}
              onChange={(e) => setEditForm({...editForm, sleeve: e.target.value})}
            />
          </div>

          <div className="form-group">
            <label>Length (cm):</label>
            <input
              type="number"
              value={editForm.length}
              onChange={(e) => setEditForm({...editForm, length: e.target.value})}
            />
          </div>

          <button onClick={handleUpdateMeasurement}>Update Measurement</button>
          <button onClick={() => setEditingId(null)}>Cancel</button>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';

interface Request {
  id: number;
  item: string;
  quantity: number;
  status: 'pending' | 'approved' | 'rejected';
}

interface InventoryItem {
  id: number;
  name: string;
  stock: number;
  category: string;
}

export function AdminPanel() {
  const [requests, setRequests] = useState<Request[]>([]);
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [newItemName, setNewItemName] = useState('');
  const [newItemStock, setNewItemStock] = useState('');
  const [newItemCategory, setNewItemCategory] = useState('');

  // Fetch requests
  useEffect(() => {
    fetch('/api/requests-api/requests')
      .then(res => res.json())
      .then(data => setRequests(data));
  }, []);

  // Fetch inventory
  useEffect(() => {
    fetch('/api/inventory-api')
      .then(res => res.json())
      .then(data => setInventory(data));
  }, []);

  const handleApprove = (id: number) => {
    fetch(`/api/approval-api/requests/${id}/approve`, {
      method: 'POST',
    });

    setRequests(requests.map(req => 
      req.id === id ? { ...req, status: 'approved' } : req
    ));
  };

  const handleReject = (id: number) => {
    fetch(`/api/approval-api/requests/${id}/reject`, {
      method: 'POST',
    });

    setRequests(requests.map(req => 
      req.id === id ? { ...req, status: 'rejected' } : req
    ));
  };

  const handleAddInventory = () => {
    fetch('/api/inventory-api', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        name: newItemName,
        stock: Number(newItemStock),
        category: newItemCategory,
      }),
    });

    setInventory([...inventory, {
      id: inventory.length + 1,
      name: newItemName,
      stock: Number(newItemStock),
      category: newItemCategory,
    }]);

    setNewItemName('');
    setNewItemStock('');
    setNewItemCategory('');
  };

  return (
    <div className="admin-panel">
      <h1>Admin Panel</h1>

      <section>
        <h2>Manage Requests</h2>
        <table>
          <thead>
            <tr>
              <th>Item</th>
              <th>Quantity</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {requests.map(request => (
              <tr key={request.id}>
                <td>{request.item}</td>
                <td>{request.quantity}</td>
                <td>{request.status}</td>
                <td>
                  <button onClick={() => handleApprove(request.id)}>Approve</button>
                  <button onClick={() => handleReject(request.id)}>Reject</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>

      <section>
        <h2>Manage Inventory</h2>
        <div>
          <input
            type="text"
            placeholder="Item Name"
            value={newItemName}
            onChange={(e) => setNewItemName(e.target.value)}
          />
          <input
            type="number"
            placeholder="Stock"
            value={newItemStock}
            onChange={(e) => setNewItemStock(e.target.value)}
          />
          <input
            type="text"
            placeholder="Category"
            value={newItemCategory}
            onChange={(e) => setNewItemCategory(e.target.value)}
          />
          <button onClick={handleAddInventory}>Add Item</button>
        </div>

        <table>
          <thead>
            <tr>
              <th>Name</th>
              <th>Stock</th>
              <th>Category</th>
            </tr>
          </thead>
          <tbody>
            {inventory.map(item => (
              <tr key={item.id}>
                <td>{item.name}</td>
                <td>{item.stock}</td>
                <td>{item.category}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>
    </div>
  );
}

